# ---------------------------------------------------------------------------
# Polymarket SDK client
# ---------------------------------------------------------------------------

def get_client():
    """Return an authenticated PolymarketUS client."""
    from polymarket_us import PolymarketUS
    if not POLYMARKET_KEY_ID or not POLYMARKET_SECRET_KEY:
        raise RuntimeError("Polymarket API credentials not configured")
    return PolymarketUS(key_id=POLYMARKET_KEY_ID, secret_key=POLYMARKET_SECRET_KEY)


def _safe_float(val):
    """Extract a float from a value, handling Amount dicts."""
    if val is None:
        return None
    if isinstance(val, dict) and "value" in val:
        val = val["value"]
    try:
        return float(val)
    except (TypeError, ValueError):
        return None


def _get(obj, *keys, default=None):
    """Get first matching key from a dict."""
    for key in keys:
        if isinstance(obj, dict) and key in obj:
            return obj[key]
    return default


# ---------------------------------------------------------------------------
# Data fetching — Polymarket SDK
# ---------------------------------------------------------------------------

def fetch_positions(client):
    try:
        response = client.portfolio.positions()
        positions_map = response.get("positions", {})
        return list(positions_map.items())
    except Exception as e:
        print(f"ERROR fetching positions: {e}")
        return []


def fetch_market_price(client, market_slug):
    try:
        bbo = client.markets.bbo(market_slug)
        best_bid = _safe_float(bbo.get("bestBidPrice") or bbo.get("bid"))
        best_ask = _safe_float(bbo.get("bestAskPrice") or bbo.get("ask"))
        if best_bid is not None and best_ask is not None:
            return (best_bid + best_ask) / 2
        return best_bid or best_ask
    except Exception:
        return None


def fetch_market(client, slug_or_id):
    try:
        return client.markets.retrieve_by_slug(slug_or_id)
    except Exception:
        try:
            return client.markets.retrieve(slug_or_id)
        except Exception:
            return None


_ACTS_CACHE_TTL = 300     # 5 min — the dashboard polls every 60s
_ACTS_CUTOFF = "2026-03-01T00:00:00+00:00"   # same cutoff the dashboard uses


def _act_detail(act: dict) -> dict:
    """The type-specific payload dict hanging off an activity."""
    for k, v in (act or {}).items():
        if k != "type" and isinstance(v, dict):
            return v
    return {}


def _act_key(act: dict) -> str:
    """Stable identity for one activity.

    Prefer the venue's own transactionId — activities are append-only
    history, but a payload hash would mint a NEW row if any field is ever
    revised (a status flipping to COMPLETED, say), and a duplicate here
    double-counts money on the dashboard. The hash is only the fallback
    for types that carry no id."""
    d = _act_detail(act)
    tid = d.get("transactionId") or d.get("id") or d.get("tradeId")
    if tid:
        return f"{act.get('type', '')}:{tid}"
    return hashlib.sha1(
        json.dumps(act, sort_keys=True, default=str).encode()).hexdigest()


def _act_at(act: dict):
    d = _act_detail(act)
    return d.get("updateTime") or d.get("timestamp") or None


def _acts_store(sb, acts: list) -> int:
    """Upsert raw activities. Returns how many rows were written."""
    rows, seen = [], set()
    for a in acts or []:
        k = _act_key(a)
        if k in seen:
            continue                       # same page can repeat a row
        seen.add(k)
        rows.append({"key": k, "at": _act_at(a), "type": a.get("type"),
                     "slug": _act_detail(a).get("marketSlug"), "payload": a})
    if not rows:
        return 0
    try:
        sb.table("poly_activities").upsert(rows, on_conflict="key").execute()
        return len(rows)
    except Exception:
        return 0


def _acts_sync(sb, client, pages: int = 3) -> dict:
    """Incremental catch-up: walk the newest pages and stop once we reach
    activity we already hold. Normally 1 page — the feed only grows by
    what the machine did in the last few minutes."""
    res = {"pages": 0, "stored": 0}
    try:
        newest = None
        try:
            r = (sb.table("poly_activities").select("at")
                 .order("at", desc=True).limit(1).execute().data) or []
            newest = r[0]["at"] if r else None
        except Exception:
            pass
        cursor = None
        for _ in range(pages):
            params = {"limit": 100}
            if cursor:
                params["cursor"] = cursor
            resp = client.portfolio.activities(params=params)
            page = resp.get("activities", []) or []
            res["pages"] += 1
            res["stored"] += _acts_store(sb, page)
            if not page or resp.get("eof", True) or not resp.get("nextCursor"):
                break
            # Caught up: this page reaches back past what we already have.
            if newest:
                oldest = min((str(_act_at(a) or "") for a in page),
                             default="")
                if oldest and oldest <= str(newest):
                    break
            cursor = resp.get("nextCursor")
    except Exception as e:
        res["err"] = str(e)[:100]
    return res


_ACTS_DEEP_TYPES = ("ACTIVITY_TYPE_TRANSFER",
                    "ACTIVITY_TYPE_LIQUIDITY_PROGRAM",
                    "ACTIVITY_TYPE_TAKER_FEE_REBATE")


def _gameday_pnl(sb) -> dict:
    """Today / yesterday by ARIZONA GAME DAY, from the venue ledger.

    ⚠ NOT by payout timestamp, and NOT by the browser's timezone (Aug 15
    2026). The dashboard used to bucket on when Polymarket credited the
    money, so a Friday night game resolving at 12:20am counted as
    Saturday — at 7am Saturday, with nothing played, the card read
    +$7.22 "today". It also asked the browser what timezone it was in.
    Arizona is the only timezone this machine has ever needed; MST, no
    DST, hardcoded.

    Settled bets only — an unplayed game's `realized_usd` is just the
    cash deployed, so counting it would show tonight's slate as a loss
    before first pitch."""
    out = {"today": None, "yesterday": None}
    az = ZoneInfo("America/Phoenix")
    today = datetime.now(timezone.utc).astimezone(az).date()
    # PRIMARY: the venue's own ledger via poly_gameday_pnl (WRITTEN AND
    # APPLIED Aug 21 2026 — the operating rules named this function as the
    # source while it did not exist, and the night it finally bit, the
    # fallback chain showed ~$76 for a -$0.98 night). Resolution rows,
    # deduped per (market, leg, side), bucketed by AZ GAME day.
    try:
        rows = (sb.rpc("poly_gameday_pnl", {"p_days": 3}).execute().data) or []
        by_day = {str(r.get("az_day")): float(r.get("realized_usd") or 0)
                  for r in rows}
        out["today"] = round(by_day.get(today.isoformat(), 0.0), 2)
        out["yesterday"] = round(
            by_day.get((today - timedelta(days=1)).isoformat(), 0.0), 2)
        return out
    except Exception:
        pass                     # RPC unreachable → the bot_picks fallback
    # FALLBACK ONLY: the per-pick ledger, final-gated (the gate is the
    # price of this path — pre-final realized_usd is just cash deployed).
    # Disconnect-retried: a dropped read here used to silently null the
    # block, which is what let the credit-time number reach the card.
    try:
        rows = (_sb_read_retry(
            lambda: sb.table("bot_picks").select("event_start,poly_pnl")
            .gte("event_start",
                 (datetime.now(timezone.utc) - timedelta(days=3)).isoformat())
            .limit(1000), label="gameday bot_picks").data) or []
        acc = {}
        for r in rows:
            p = r.get("poly_pnl") or {}
            if not p.get("final"):
                continue
            try:
                d = datetime.fromisoformat(
                    str(r["event_start"]).replace("Z", "+00:00")
                ).astimezone(az).date()
                acc[d] = acc.get(d, 0.0) + float(p.get("realized_usd") or 0)
            except (TypeError, ValueError, KeyError):
                continue
        out["today"] = round(acc.get(today, 0.0), 2)
        out["yesterday"] = round(acc.get(today - timedelta(days=1), 0.0), 2)
    except Exception:
        pass
    return out


_INCENTIVE_SYNC_MOD = 10   # minutes between incentive pulls (two venue GETs)
_INCENTIVE_MAX_PAGES = 60  # program-catalog page cap; res['truncated'] flags
                           # a hit so a growing catalog can't silently clip


def _incentives_sync(sb, client) -> dict:
    """Mirror the venue's liquidity-incentive truth into Supabase.

    Two reads, both authenticated (the SDK's client.get defaults
    authenticated=False — that default cost us four probe rounds):
      /v1/incentives/earnings -> per market, per ET day, PAID/PENDING/
                                 SKIPPED. The ONLY source of accrual;
                                 the activities feed shows PAID only.
      /v1/incentives          -> the full program catalog: rewardPool,
                                 discountFactor and TARGET SIZE per
                                 market and time period.

    Never raises — a reward outage must not take the tick down."""
    res = {"earnings": 0, "programs": 0, "merged": 0, "err": None}
    try:
        data = client.get("/v1/incentives/earnings", authenticated=True) or {}
        rows = data.get("rewards") or []
        # ⚠ STATUS IS PART OF THE KEY. Per the API reference: "A single
        # market on a single date may return multiple rows — one per payout
        # status (PAID, PENDING, SKIPPED)." Keying without status collapses
        # a part-paid/part-pending market-day into one mislabelled row and
        # destroys the accrual split this mirror exists for.
        # Earnings is NOT paginated; startDate defaults to 2026-03-21, so
        # one call returns full history.
        payload, seen = [], set()
        for r in rows:
            slug = str(r.get("marketSlug") or "").strip()
            day = str(r.get("date") or "").strip()[:10]
            ptype = str(r.get("programType") or "liquidityProgram")
            st = str(r.get("status") or "").strip().upper()
            if not slug or not day or not st:
                continue
            k = (slug, day, ptype, st)
            if k in seen:      # same key twice in one response ⇒ sum
                for p in payload:
                    if (p["market_slug"], p["earn_date"],
                            p["program_type"], p["status"]) == k:
                        p["reward"] = round(
                            p["reward"] + (_safe_float(r.get("reward")) or 0), 4)
                        res["merged"] += 1
                        break
                continue
            seen.add(k)
            payload.append({
                "market_slug": slug, "earn_date": day, "program_type": ptype,
                "status": st, "reward": round(_safe_float(r.get("reward")) or 0, 4),
                "updated_at": datetime.now(timezone.utc).isoformat(),
            })
        for i in range(0, len(payload), 300):
            (sb.table("poly_incentive_earnings").upsert(
                payload[i:i + 300],
                on_conflict="market_slug,earn_date,program_type,status")
             .execute())
        res["earnings"] = len(payload)

        # ⚠ STATUS TRANSITIONS SUPERSEDE, THEY DO NOT ACCUMULATE.
        # status is part of the key (a market-day really can carry more
        # than one status), but a row does not stay PENDING once it is
        # PAID — the venue flips it. An upsert-only sync therefore leaves
        # the stale PENDING row alongside the new PAID one and DOUBLE
        # COUNTS the day. Caught Aug 17 2026 with 162 market-days and
        # $24.99 of phantom pending on the books, inflating every rent
        # figure by roughly the paid amount.
        #
        # The venue's own response is the authority: whatever statuses it
        # returned for a (slug, day, program) this pull are the only ones
        # that exist. Anything else we hold for that key is stale.
        try:
            keys: dict = {}
            for p in payload:
                keys.setdefault((p["market_slug"], p["earn_date"],
                                 p["program_type"]), set()).add(p["status"])
            stale = 0
            for (slug, day, ptype), live in keys.items():
                dead = [s for s in ("PAID", "PENDING", "SKIPPED")
                        if s not in live]
                if not dead:
                    continue
                r = (sb.table("poly_incentive_earnings").delete()
                     .eq("market_slug", slug).eq("earn_date", day)
                     .eq("program_type", ptype).in_("status", dead)
                     .execute())
                stale += len(getattr(r, "data", None) or [])
            res["stale_removed"] = stale
        except Exception as e:
            res["stale_err"] = f"{type(e).__name__}: {e}"[:120]
    except Exception as e:
        res["err"] = f"earnings: {type(e).__name__}: {e}"[:200]

    try:
        # ⚠ /v1/incentives IS PAGINATED (pageToken / nextPageToken). The
        # first cut read page 1 only and concluded — wrongly — that prop
        # markets have no incentive programs at all, while our own earnings
        # feed showed props earning. Walk every page. Public endpoint (no
        # auth required), rate limit 5 rps.
        payload, token, pages, last_size = [], None, 0, -1
        while pages < _INCENTIVE_MAX_PAGES:
            q = {"pageSize": 200}
            if token:
                q["pageToken"] = token
            cat = client.get("/v1/incentives", query=q,
                             authenticated=True) or {}
            for m in (cat.get("programs") or []):
                slug = str(m.get("marketSlug") or "").strip()
                if not slug:
                    continue
                for tp in (m.get("timePeriods") or []):
                    pid = str(tp.get("programId") or "").strip()
                    if not pid:
                        continue
                    payload.append({
                        "market_slug": slug, "program_id": pid,
                        "program_type": tp.get("programType"),
                        "period": tp.get("period"),
                        "starts_at": tp.get("start") or None,
                        # omitted while a live game is still in progress
                        "ends_at": tp.get("end") or None,
                        "reward_pool": _safe_float(tp.get("rewardPool")),
                        "discount_factor": _safe_float(tp.get("discountFactor")),
                        "target_size": _safe_float(tp.get("targetSize")),
                        "status": tp.get("status"),
                        "category": m.get("category") or None,
                        "subcategory": m.get("subcategory") or None,
                        "event_start": m.get("eventStartTime") or None,
                        "synced_at": datetime.now(timezone.utc).isoformat(),
                    })
            pages += 1
            token = cat.get("nextPageToken") or cat.get("next_page_token")
            # The venue returns a nextPageToken even at the end of the
            # catalog, so trusting it alone spins the full page cap over
            # the same 100 markets (observed: 60 pages, 318 rows, zero new).
            # Stop when a page adds nothing new.
            grew = len({(p["market_slug"], p["program_id"]) for p in payload})
            if not token or grew == last_size:
                break
            last_size = grew
            _time.sleep(0.21)      # 5 rps limit
        res["pages"] = pages
        res["truncated"] = bool(token)   # hit the page cap with more to come

        # ⚠ THE UNFILTERED CATALOG DOES NOT LIST OUR MARKETS. Walking every
        # page returns ~100 markets (politics + a few game MLs) and ZERO
        # player-prop programs — while the earnings feed shows props paying.
        # The programs are real and only surface via the `symbols` filter.
        # So explicitly ask for the slugs we actually rest orders on.
        want = set()
        try:
            since = (datetime.now(timezone.utc) - timedelta(days=4)).isoformat()
            er = (sb.table("poly_incentive_earnings").select("market_slug")
                  .gte("earn_date",
                       (datetime.now(timezone.utc).date()
                        - timedelta(days=4)).isoformat())
                  .limit(600).execute().data) or []
            want.update(str(r["market_slug"]) for r in er if r.get("market_slug"))
            bp = (sb.table("bot_picks").select("signal_blob")
                  .gte("picked_at", since).limit(400).execute().data) or []
            for r in bp:
                b = r.get("signal_blob") or {}
                s = (b.get("pmm") or {}).get("slug") or b.get("pmm_slug")
                if s:
                    want.add(str(s))
        except Exception as e:
            res["symbols_src_err"] = str(e)[:120]
        want = sorted(want)[:400]
        res["symbols_asked"] = len(want)
        sym_payload, enc = [], None
        for i in range(0, len(want), 20):
            chunk = want[i:i + 20]
            got = None
            # the array encoding isn't documented; try a real list first,
            # then comma-joined, and record which one the venue accepted
            for mode, val in (("list", chunk), ("csv", ",".join(chunk))):
                try:
                    r2 = client.get("/v1/incentives", query={"symbols": val},
                                    authenticated=True) or {}
                    if r2.get("programs"):
                        got, enc = r2, enc or mode
                        break
                except Exception:
                    continue
            if not got:
                continue
            for m in (got.get("programs") or []):
                slug = str(m.get("marketSlug") or "").strip()
                if not slug:
                    continue
                for tp in (m.get("timePeriods") or []):
                    pid = str(tp.get("programId") or "").strip()
                    if not pid:
                        continue
                    sym_payload.append({
                        "market_slug": slug, "program_id": pid,
                        "program_type": tp.get("programType"),
                        "period": tp.get("period"),
                        "starts_at": tp.get("start") or None,
                        "ends_at": tp.get("end") or None,
                        "reward_pool": _safe_float(tp.get("rewardPool")),
                        "discount_factor": _safe_float(tp.get("discountFactor")),
                        "target_size": _safe_float(tp.get("targetSize")),
                        "status": tp.get("status"),
                        "category": m.get("category") or None,
                        "subcategory": m.get("subcategory") or None,
                        "event_start": m.get("eventStartTime") or None,
                        "synced_at": datetime.now(timezone.utc).isoformat(),
                    })
            _time.sleep(0.21)          # 5 rps
        res["symbols_encoding"] = enc
        payload.extend(sym_payload)
        # de-dup within the batch: upsert rejects repeated keys in one call
        uniq = {}
        for p in payload:
            uniq[(p["market_slug"], p["program_id"])] = p
        payload = list(uniq.values())
        for i in range(0, len(payload), 300):
            (sb.table("poly_incentive_programs").upsert(
                payload[i:i + 300],
                on_conflict="market_slug,program_id").execute())
        res["programs"] = len(payload)
    except Exception as e:
        res["err"] = ((res["err"] or "") +
                      f" | programs: {type(e).__name__}: {e}")[:300]

    try:
        (sb.table("poly_incentive_sync").upsert({
            "id": 1, "ran_at": datetime.now(timezone.utc).isoformat(),
            "earnings_rows": res["earnings"], "program_rows": res["programs"],
            "note": res["err"] or "ok"}).execute())
    except Exception:
        pass
    return res


def _incentive_day_rewards(sb, days: int = 3) -> dict:
    """{AZ date -> {'total','paid','pending','skipped'}} of liquidity
    earnings, for the day cards.

    ⚠ earn_date is EASTERN per the venue; this project reports ARIZONA
    days. A reward "date" is the ET calendar day the order was resting,
    which is the same wall-clock window as an AZ evening slate offset by
    three hours — there is no clean mapping, so we do NOT pretend one.
    The ET day is carried through as-is and LABELLED as ET, rather than
    shifted by a guess."""
    out: dict = {}
    try:
        since = (datetime.now(timezone.utc).date() - timedelta(days=days + 2))
        rows = (sb.table("poly_incentive_earnings")
                .select("earn_date,status,reward")
                .gte("earn_date", since.isoformat())
                .limit(2000).execute().data) or []
        for r in rows:
            d = str(r.get("earn_date") or "")[:10]
            if not d:
                continue
            b = out.setdefault(d, {"total": 0.0, "paid": 0.0,
                                   "pending": 0.0, "skipped": 0.0})
            amt = _safe_float(r.get("reward")) or 0.0
            st = str(r.get("status") or "").upper()
            b["total"] += amt
            b[{"PAID": "paid", "PENDING": "pending",
               "SKIPPED": "skipped"}.get(st, "pending")] += amt
        for b in out.values():
            for k in b:
                b[k] = round(b[k], 4)
    except Exception:
        pass
    return out


def _rent_window(sb, days: int = 7) -> dict:
    """Liquidity rent over a trailing window — PAID + PENDING.

    A single day's rent is not measurable: the venue publishes a day only
    after its reward periods end and may compute for up to 5 business
    days, so recent days are always still filling in (observed 8.83 →
    3.57 → 0.78 walking toward today, which is fill-in, not decline).
    A trailing window is the only honest read until the lag is measured.

    PAID + PENDING is the basis; SKIPPED is EXCLUDED because it is money
    we never receive — days that never reached the $1.00 minimum payout.

    ⚠ This UNDERCOUNTS by design. The newest day or two are incomplete,
    so the number is a floor that drifts up as they settle — never read a
    week-over-week dip as a decline. `newest_date` is returned so a caller
    can show how current the data actually is."""
    out = {"total": 0.0, "paid": 0.0, "pending": 0.0, "skipped": 0.0,
           "days": days, "newest_date": None, "n_markets": 0}
    try:
        az = ZoneInfo("America/Phoenix")
        today = datetime.now(timezone.utc).astimezone(az).date()
        since = today - timedelta(days=days - 1)
        rows = (sb.table("poly_incentive_earnings")
                .select("earn_date,status,reward,market_slug")
                .gte("earn_date", since.isoformat())
                .limit(5000).execute().data) or []
        slugs = set()
        for r in rows:
            amt = _safe_float(r.get("reward")) or 0.0
            st = str(r.get("status") or "").upper()
            d = str(r.get("earn_date") or "")[:10]
            if d and (out["newest_date"] is None or d > out["newest_date"]):
                out["newest_date"] = d
            if st == "SKIPPED":
                out["skipped"] += amt
                continue          # forfeited — never counted as earnings
            out["paid" if st == "PAID" else "pending"] += amt
            out["total"] += amt
            if r.get("market_slug"):
                slugs.add(r["market_slug"])
        out["n_markets"] = len(slugs)
        for k in ("total", "paid", "pending", "skipped"):
            out[k] = round(out[k], 2)
    except Exception:
        pass
    return out


def _window_pnl(sb, days: int = 7) -> float | None:
    """Trading P&L over the trailing window, by ARIZONA game day, settled
    bets only — the same basis as the day cards so the two can be added."""
    try:
        az = ZoneInfo("America/Phoenix")
        today = datetime.now(timezone.utc).astimezone(az).date()
        since = today - timedelta(days=days - 1)
        rows = (sb.table("bot_picks").select("event_start,poly_pnl")
                .gte("event_start",
                     (datetime.now(timezone.utc)
                      - timedelta(days=days + 2)).isoformat())
                .limit(3000).execute().data) or []
        tot = 0.0
        for r in rows:
            p = r.get("poly_pnl") or {}
            if not p.get("final"):
                continue
            try:
                d = datetime.fromisoformat(
                    str(r["event_start"]).replace("Z", "+00:00")
                ).astimezone(az).date()
            except (TypeError, ValueError, KeyError):
                continue
            if since <= d <= today:
                tot += float(p.get("realized_usd") or 0)
        return round(tot, 2)
    except Exception:
        return None


def _all_in(pnl, rewards):
    """Trading P&L + liquidity rent for a day, or None if we don't have
    the trading half. Rewards alone are not a day's result."""
    if pnl is None:
        return None
    return round(float(pnl) + float(rewards or 0), 2)


def _rent_by_day(sb, since) -> dict | None:
    """Liquidity rent bucketed by earn_date (PAID+PENDING, SKIPPED out),
    paged — a YTD read of poly_incentive_earnings can exceed the 1,000-row
    PostgREST cap (gotcha #40). Returns {date: usd} or None on failure —
    a missing rent half must render as a dash, never as $0.00."""
    try:
        rows = _sb_paged(lambda: (
            sb.table("poly_incentive_earnings")
            .select("earn_date,status,reward")
            .gte("earn_date", since.isoformat())
            .order("earn_date")), max_pages=30)
        out: dict = {}
        for r in rows:
            if str(r.get("status") or "").upper() == "SKIPPED":
                continue          # forfeited — never counted as earnings
            d = str(r.get("earn_date") or "")[:10]
            if d:
                out[d] = out.get(d, 0.0) + (_safe_float(r.get("reward")) or 0.0)
        return out
    except Exception:
        return None


def _pnl_stack(sb) -> dict | None:
    """The P&L stack (mockup E, Aug 22 2026): Today/Yesterday bets-only,
    then 7d / 30d / YTD all-in with the bets-vs-rent split per window.

    ONE venue read for every bets number: poly_gameday_pnl walked back to
    Jan 1 gives per-AZ-game-day realized USD, and the windows are sums
    over the same rows the day cards read — no second accounting basis.
    Rent buckets by EARN date (the day the resting orders earned it), so
    a window answers "how did the machine do", not "when did the venue
    pay" — the payout lag is why the day cards say bets-only.

    Returns None when the venue RPC is unreachable — the card shows
    dashes; a partial stack would put two different lies side by side."""
    az = ZoneInfo("America/Phoenix")
    today = datetime.now(timezone.utc).astimezone(az).date()
    jan1 = today.replace(month=1, day=1)
    ytd_days = (today - jan1).days + 1
    try:
        rows = (sb.rpc("poly_gameday_pnl",
                       {"p_days": ytd_days}).execute().data) or []
    except Exception:
        return None
    by_day: dict = {}
    for r in rows:
        d = str(r.get("az_day") or "")[:10]
        if d:
            by_day[d] = by_day.get(d, 0.0) + float(r.get("realized_usd") or 0)
    rent = _rent_by_day(sb, jan1)

    def _win(days: int) -> dict:
        since = (today - timedelta(days=days - 1)).isoformat()
        bets = round(sum(v for d, v in by_day.items() if d >= since), 2)
        rw = (None if rent is None else
              round(sum(v for d, v in rent.items() if d >= since), 2))
        return {"bets": bets, "rent": rw,
                "total": round(bets + (rw or 0), 2)}

    out = {"today": round(by_day.get(today.isoformat(), 0.0), 2),
           "yesterday": round(
               by_day.get((today - timedelta(days=1)).isoformat(), 0.0), 2),
           "d7": _win(7), "d30": _win(30), "ytd": _win(ytd_days)}
    # YTD's headline is the CASH EQUATION, not the settle-basis sum (user,
    # Aug 22 2026: "Cash ledger 12/31/25. Cash ledger today. Tada.") — the
    # settle basis read -$256 for a year the cash ledger closes at ~+$95,
    # because it can't see sell-to-close profits (no resolution row) or
    # the ~$179 of outage/promo credits. Ship the year's deposits and
    # withdrawals; the page adds the live balance:
    #   ytd_cash = balance + wd_ytd - dep_ytd
    # Year-start balance is NOT netted: the account was 3 weeks old with
    # ~$20 in it at NYE (recorded: $25 in, -$31 realized, i.e. some launch
    # credit the feed never recorded), so the anchor is ~$0-40 of fuzz on
    # a $3.7k year — labeled, not modeled. bets/rent stay in the row as
    # composition; the remainder is sells + credits.
    try:
        rows = sb.table("poly_activities").select("type,payload") \
            .in_("type", ["ACTIVITY_TYPE_ACCOUNT_DEPOSIT",
                          "ACTIVITY_TYPE_ACCOUNT_WITHDRAWAL"]) \
            .gte("at", jan1.isoformat()).limit(1000).execute().data or []
        dep = wd = 0.0
        for r in rows:
            try:
                amt = abs(float(((r.get("payload") or {})
                                 .get("accountBalanceChange") or {})
                                .get("amount", {}).get("value")))
            except (TypeError, ValueError, AttributeError):
                continue
            if r["type"] == "ACTIVITY_TYPE_ACCOUNT_DEPOSIT":
                dep += amt
            else:
                wd += amt
        out["ytd"]["dep"] = round(dep, 2)
        out["ytd"]["wd"] = round(wd, 2)
    except Exception:
        pass                      # no flows -> the page keeps settle-basis
    try:
        out["rent_days"] = _rent_days_recent(sb)
    except Exception:
        pass                      # widget hides; the stack stays whole
    return out


def _rent_days_recent(sb, n_days: int = 5) -> list:
    """RENT BY DAY (user, Aug 25 2026: "I ask this every day, lol") — the
    last N earn-days with the paid/pending split, straight off the
    ledger. A day with no rows is None (the venue posts earn-days ~a
    day behind; "not posted yet" must render as a dash, never $0.00).
    Own helper because the cached pnl_stack is computed by the BOX —
    frozen code through Aug 27 — so /api/data patches this key into a
    cached stack that predates it."""
    az = ZoneInfo("America/Phoenix")
    today = datetime.now(timezone.utc).astimezone(az).date()
    since = (today - timedelta(days=n_days)).isoformat()
    rows = (sb.table("poly_incentive_earnings")
            .select("earn_date,status,reward")
            .gte("earn_date", since).limit(1000).execute().data) or []
    agg: dict = {}
    for r in rows:
        st = str(r.get("status") or "").upper()
        if st == "SKIPPED":
            continue
        d = str(r.get("earn_date") or "")[:10]
        if not d:
            continue
        a = agg.setdefault(d, {"paid": 0.0, "pending": 0.0})
        a["pending" if st == "PENDING" else "paid"] += (
            _safe_float(r.get("reward")) or 0.0)
    days = []
    for i in range(n_days):
        d = (today - timedelta(days=i)).isoformat()
        a = agg.get(d)
        days.append({"d": d,
                     "paid": None if a is None else round(a["paid"], 2),
                     "pending": (None if a is None
                                 else round(a["pending"], 2))})
    return days


def _gameday_rewards(sb) -> dict:
    """{'today': {...}, 'yesterday': {...}} liquidity rewards, PENDING
    included, for the day cards.

    ⚠ TIMEZONE, stated rather than fudged: the venue stamps each reward
    row with an EASTERN calendar day; this project reports ARIZONA game
    days. For an evening slate the two line up, but they are not the same
    unit and a late-night ET rollover will land a reward on the next ET
    day while the game stays on tonight's AZ card. We match the dates
    directly and LABEL it, instead of shifting by a guess."""
    out = {"today": None, "yesterday": None}
    try:
        az = ZoneInfo("America/Phoenix")
        today = datetime.now(timezone.utc).astimezone(az).date()
        days = _incentive_day_rewards(sb, days=4)
        for label, d in (("today", today),
                         ("yesterday", today - timedelta(days=1))):
            b = days.get(d.isoformat())
            # ⚠ ABSENT ≠ ZERO. The venue publishes a day's rent only after
            # its periods end (day_of runs T-6h→first pitch, live runs
            # start→settlement) and computes "within 5 business days". So
            # the current day almost always has NO ROW, and rendering that
            # as "+$0.00" reads as "earned nothing" when the truth is "not
            # reported yet". `unpublished` lets the card say so.
            out[label] = (dict(b, unpublished=False) if b else
                          {"total": 0.0, "paid": 0.0, "pending": 0.0,
                           "skipped": 0.0, "unpublished": True})
    except Exception:
        pass
    return out


@app.route("/api/polymarket/earnings-raw")
def api_poly_earnings_raw():
    """RAW /v1/incentives/earnings rows + the orders we had on those markets.

    `_incentives_sync` keeps only five fields (slug, date, programType,
    status, reward). If the venue also returns qualifying size, resting
    time, or our share, that is the missing input to the rent formula --
    and we would have been throwing it away on every sync. This dumps the
    UNPARSED rows so the question is answerable by looking rather than by
    modelling.

    ?slug= filters (substring). ?n= caps rows (default 8).
    """
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    want_slug = (request.args.get("slug") or "").strip().lower()
    try:
        n = max(1, min(40, int(request.args.get("n") or 8)))
    except Exception:
        n = 8
    out: dict = {"ok": True}
    try:
        client = get_client()
        data = client.get("/v1/incentives/earnings", authenticated=True) or {}
        rows = data.get("rewards") or []
        out["envelope_keys"] = sorted(data.keys())
        out["total_rows"] = len(rows)
        if rows:
            out["row_keys"] = sorted(rows[0].keys()) if isinstance(rows[0], dict) else None
        sel = [r for r in rows
               if not want_slug
               or want_slug in str(r.get("marketSlug") or "").lower()]
        sel = sorted(sel, key=lambda r: float(r.get("reward") or 0), reverse=True)
        out["rows"] = sel[:n]
        # What we had resting on those markets, from our own book.
        slugs = [str(r.get("marketSlug") or "") for r in sel[:n]]
        try:
            sb = get_supabase()
            pk = (sb.table("bot_picks")
                  .select("event_name,market_type,side,entry_price,picked_at,"
                          "event_start,contracts:signal_blob->>contracts,"
                          "pmm_slug:signal_blob->>pmm_slug")
                  .in_("signal_blob->>pmm_slug", slugs)
                  .limit(60).execute().data) or []
            out["our_picks"] = pk
        except Exception as e:
            out["picks_err"] = f"{type(e).__name__}: {e}"[:160]
    except Exception as e:
        out.update(ok=False, error=f"{type(e).__name__}: {e}"[:220])
    return jsonify(out)


@app.route("/api/polymarket/book")
def api_poly_book():
    """READ-ONLY: the full order-book ladder for one slug, plus depth totals.

    THE MEASUREMENT THIS MACHINE HAS NEVER HAD. Rent is our share of the
    qualifying depth on a market, and depth is captured NOWHERE --
    pm_snapshots stores prices, not sizes -- so every claim about why one
    market pays and another does not has been derived from the payout and
    an assumed share model rather than measured. That is backwards, and it
    produced an "implied ~234 contracts" figure that the account owner
    rejected on sight.

    Also reports where OUR resting order sits in that ladder, because the
    two questions that matter are the same question: how much is in front
    of us, and how much is behind.

    Shared-secret, no writes.
    """
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    slug = (request.args.get("slug") or "").strip()
    if not slug:
        return jsonify({"ok": False, "error": "pass ?slug="}), 400
    out: dict = {"ok": True, "slug": slug}
    try:
        client = get_client()
        bk = _pmm_book(client, slug) or {}
        bids, asks = bk.get("bids") or [], bk.get("asks") or []
        out["best_bid"], out["best_ask"] = bk.get("best_bid"), bk.get("best_ask")
        out["bids"] = [{"c": c, "qty": q} for c, q in bids[:12]]
        out["asks"] = [{"c": c, "qty": q} for c, q in asks[:12]]
        out["bid_depth"] = round(sum(q for _, q in bids), 1)
        out["ask_depth"] = round(sum(q for _, q in asks), 1)
        bb = bk.get("best_bid")
        if bb is not None:
            for band in (1, 3, 5):
                out[f"bid_depth_within_{band}c"] = round(
                    sum(q for c, q in bids if c >= bb - band), 1)
        # Our own resting orders on this slug, and what sits ahead of them.
        try:
            _r = client.orders.list({"slugs": [slug]})
            _raw = (_r.get("orders") if isinstance(_r, dict)
                    else getattr(_r, "orders", [])) or []
            mine = []
            for _o in _raw:
                def _og(k, d=None):
                    return (_o.get(k, d) if isinstance(_o, dict)
                            else getattr(_o, k, d))
                if str(_og("state") or "") not in _OPEN_ORDER_STATES:
                    continue
                _p = _og("price")
                pv = (_p.get("value") if isinstance(_p, dict) else _p)
                canon = round(float(pv) * 100.0, 1)
                short = "SHORT" in str(_og("intent") or "")
                # BUY_SHORT reports the YES-canonical price; our real
                # per-share price is the complement (gotcha #23).
                ours_c = round(100.0 - canon, 1) if short else canon
                mine.append({
                    "intent": _og("intent"), "canon_c": canon,
                    "our_side_c": ours_c, "qty": _og("quantity"),
                    "leaves": _og("leavesQuantity"),
                    "flag": _og("manualOrderIndicator"),
                    # DEPTH IN FRONT OF US, ON THE LADDER WE ACTUALLY REST
                    # ON. A BUY_SHORT of YES is a SELL of YES, so it queues
                    # on the ASK side at the canonical price and the orders
                    # ahead of it are the CHEAPER asks. Walking the bids for
                    # it (the first cut of this endpoint) reported 0 ahead
                    # for an order that may be behind a hundred others.
                    "rests_on": "ask" if short else "bid",
                    "ahead_qty": round(
                        sum(q for c, q in asks if c < canon) if short
                        else sum(q for c, q in bids if c > canon), 1)})
            out["mine"], out["mine_count"] = mine, len(mine)
        except Exception as e:
            out["mine_err"] = f"{type(e).__name__}: {e}"[:160]
    except Exception as e:
        out.update(ok=False, error=f"{type(e).__name__}: {e}"[:220])
    return jsonify(out)


@app.route("/api/polymarket/orders")
def api_poly_orders():
    """READ-ONLY: every open order on the account. Venue truth, no writes.

    "What am I quoting right now" had no read a session could reach.
    /api/my-orders is Firebase-gated, so a sandbox has no path to it;
    dedup-orders deliberately excludes hand-placed MANUAL orders (that
    exclusion is a safety property, not an oversight); and probe-exec's
    listing is slug-filtered, i.e. it needs the answer as its input.

    What that left was GUESSING slugs, which produced two confident wrong
    readings of a football market that does not exist: Polymarket posts
    football spreads as a LADDER, one market per rung, so there is no
    `asc-nfl-<away>-<home>-<date>` to ask about. An invented slug returns
    "nothing active", which reads exactly like "pays nothing" -- the shape
    of every wrong zero in this file.

    Shared-secret like its sibling sweeps. Filters to _OPEN_ORDER_STATES,
    so a REPLACED husk stays invisible here exactly as it is everywhere
    else; use probe-exec's list_only for those.
    """
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    want_slug = (request.args.get("slug") or "").strip().lower()
    # all=1: include TERMINAL states (REJECTED/CANCELED/EXPIRED...). Added
    # Aug 23 2026 chasing 19 football creates that returned real ids and
    # were gone minutes later — REJECTED (async post-only, peg crossed)
    # and CANCELED (venue killed a resting order) need different fixes,
    # and only the terminal state can say which. Read-only either way.
    want_all = (request.args.get("all") or "") in ("1", "true", "yes")
    out: dict = {"ok": True, "orders": [], "count": 0}
    try:
        client = get_client()
        _r = client.orders.list({})
        _raw = (_r.get("orders") if isinstance(_r, dict)
                else getattr(_r, "orders", [])) or []
        rows = []
        for _o in _raw:
            def _og(k, d=None):
                return (_o.get(k, d) if isinstance(_o, dict)
                        else getattr(_o, k, d))
            st = str(_og("state") or "")
            if st not in _OPEN_ORDER_STATES and not want_all:
                continue
            sl = str(_og("marketSlug") or "")
            if want_slug and want_slug not in sl.lower():
                continue
            _p = _og("price")
            rows.append({
                "slug": sl, "state": st, "intent": _og("intent"),
                "price": (_p.get("value") if isinstance(_p, dict) else _p),
                "qty": _og("quantity"), "leaves": _og("leavesQuantity"),
                "filled": _og("cumQuantity"),
                "flag": _og("manualOrderIndicator"),
                "good_till": str(_og("goodTillTime") or "")})
        rows.sort(key=lambda r: str(r.get("slug") or ""))
        out["orders"], out["count"] = rows, len(rows)
    except Exception as e:
        out.update(ok=False, error=f"{type(e).__name__}: {e}"[:220])
    return jsonify(out)


@app.route("/api/polymarket/dedup-orders")
def api_poly_dedup_orders():
    """Cancel DUPLICATE resting BUY orders — one order per (slug, intent).

    Aug 16 2026. Found live: two 5-contract BUYs resting on the same YRFI
    slug, created 2.2 SECONDS apart, against a single bot_picks row. Cause
    was overlapping topup batches — each CALL is bounded, but concurrent
    calls are not safe against each other: two passes read the same order,
    one won the cancel, both created. One-order-per-slug is an INVARIANT
    (the re-peg cancels a single order_id per bet, so any twin is stranded
    at the old price the moment the book moves, and the position is double
    the size the row claims).

    ⚠ BUY INTENTS ONLY. The harvest ladder rests THREE sells per slug at
    +40/+50/+65% by design — deduping sells would dismantle it.

    Keeps the OLDEST order in each duplicate group (it holds the queue
    position and matches the logged entry) and cancels the rest. Three
    gates, all required: AUTOMATIC flag (hand-placed MANUAL orders can
    never be touched), a BUY intent, and the slug must belong to one of
    our own model picks. &dry=1 lists without cancelling."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    dry = (request.args.get("dry") or "") in ("1", "true", "yes")
    out = {"ok": True, "dry": dry, "groups": 0, "canceled": 0, "actions": []}
    try:
        sb, client = get_supabase(), get_client()
        owner = _kalshi_owner_uid()
        if not owner:
            out.update(ok=False, error="no owner uid")
            return jsonify(out)
        # slugs we actually bet — never touch anything else
        rows = (sb.table("bot_picks").select("signal_blob")
                .eq("asked_by", owner).eq("status", "pending")
                .gte("event_start", (datetime.now(timezone.utc)
                                     - timedelta(hours=12)).isoformat())
                .limit(600).execute().data) or []
        mine = set()
        for r in rows:
            b = r.get("signal_blob") or {}
            sl = (b.get("pmm") or {}).get("slug") or b.get("pmm_slug")
            if sl:
                mine.add(str(sl))
        try:
            resp = client.orders.list()
            raw = (resp.get("orders") if isinstance(resp, dict)
                   else getattr(resp, "orders", [])) or []
        except Exception as e:
            out.update(ok=False, error=f"orders.list: {e}"[:200])
            return jsonify(out)
        groups: dict = {}
        for o in raw:
            def _g(k, d=None):
                return o.get(k, d) if isinstance(o, dict) else getattr(o, k, d)
            if (_g("state") or "") not in _OPEN_ORDER_STATES:
                continue
            intent = str(_g("intent") or "")
            if "BUY" not in intent:
                continue            # ⚠ sells are laddered on purpose
            if (str(_g("manualOrderIndicator") or "")
                    != "MANUAL_ORDER_INDICATOR_AUTOMATIC"):
                continue            # never touch a hand-placed order
            md = _g("marketMetadata") or {}
            slug = ((md.get("slug") if isinstance(md, dict)
                     else getattr(md, "slug", None)) or "")
            if slug not in mine:
                continue
            groups.setdefault((slug, intent), []).append({
                "id": _g("id"), "created": str(_g("createTime") or ""),
                "price": ((_g("price") or {}).get("value")
                          if isinstance(_g("price"), dict) else None),
                "qty": _safe_float(_g("quantity")) or 0.0})
        for (slug, intent), lst in groups.items():
            if len(lst) < 2:
                continue
            out["groups"] += 1
            lst.sort(key=lambda x: x["created"])      # oldest first = keeper
            keep, extras = lst[0], lst[1:]
            for e in extras:
                act = {"slug": slug, "cancel_id": e["id"],
                       "cancel_price": e["price"], "cancel_qty": e["qty"],
                       "kept_id": keep["id"], "kept_price": keep["price"],
                       "created": e["created"]}
                if dry:
                    act["dry"] = True
                else:
                    try:
                        client.orders.cancel(e["id"], {"marketSlug": slug})
                        out["canceled"] += 1
                        act["canceled"] = True
                    except Exception as ex:
                        act["error"] = f"{type(ex).__name__}: {ex}"[:160]
                    _time.sleep(0.25)        # venue rate limit — a probe
                                             # sweep already hit Cloudflare
                out["actions"].append(act)
    except Exception as e:
        out.update(ok=False, error=f"{type(e).__name__}: {e}"[:200])
    _probe_log(out)
    return jsonify(out)


