@app.route("/api/polymarket/last-reward")
def api_poly_last_reward():
    """One-shot reward scan (Aug 4 2026, user: "when was my last maker
    reward?"): walks the account's activities newest-first and returns the
    most recent maker-reward / fee-rebate payouts. Shared-secret (?key=
    FILLS_CRON_SECRET) so the site-curl Actions bridge can trigger it from
    a sandbox session; result PERSISTED to exec_probe_runs so the answer
    reads from the DB. Read-only."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    try:
        client = get_client()
    except Exception as e:
        return jsonify({"ok": False, "error": f"client: {e}"}), 500
    acts = fetch_activities(client, max_pages=60)
    rewards = []
    for act in acts:
        t = act.get("type")
        if t in ("ACTIVITY_TYPE_LIQUIDITY_PROGRAM",
                 "ACTIVITY_TYPE_TAKER_FEE_REBATE",
                 "ACTIVITY_TYPE_TRANSFER"):
            d = act.get("accountBalanceChange") or act.get("transfer") or {}
            rewards.append({
                "type": t,
                "amount": _safe_float(d.get("amount")),
                "time": str(d.get("updateTime") or ""),
                "raw": act,      # full payload — memo/reason settles promo-vs-reward
            })
    rewards.sort(key=lambda r: r["time"], reverse=True)
    oldest_seen = ""
    for act in acts[-5:]:
        for v in act.values():
            if isinstance(v, dict) and v.get("updateTime"):
                oldest_seen = str(v["updateTime"])
    out = {"ok": True, "activities_scanned": len(acts),
           "oldest_activity_seen": oldest_seen,
           "rewards_found": len(rewards), "latest": rewards[:8]}
    try:
        get_supabase().table("exec_probe_runs").insert(
            {"params": {"kind": "last_reward"}, "result": out}).execute()
    except Exception:
        pass
    return jsonify(out)


@app.route("/api/docs-fetch")
def api_docs_fetch():
    """Read Polymarket's OWN documentation, server-side.

    Aug 16 2026, after an expensive lesson: every reward figure in this
    repo was reverse-engineered from the activities feed for weeks while
    /v1/incentives/earnings sat documented the whole time. The Claude
    sandbox has docs.polymarket.us egress-BLOCKED, so a session cannot
    read the docs directly — Vercel can. This closes that gap: no more
    guessing at a vendor that publishes everything.

    Shared-secret + HOST-ALLOWLISTED (Polymarket docs/help only) so it
    can't be used as a general fetch primitive. GET only, no redirects
    off-allowlist, body truncated, result persisted to exec_probe_runs."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    url = (request.args.get("url") or "").strip()
    allow = ("docs.polymarket.us", "polymarket.us", "docs.polymarket.com",
             "help.polymarket.com", "learn.polymarket.com")
    try:
        from urllib.parse import urlparse as _up
        host = (_up(url).hostname or "").lower()
    except Exception:
        host = ""
    if not url.startswith("https://") or host not in allow:
        return jsonify({"ok": False, "error": "host not allowed",
                        "host": host, "allow": list(allow)}), 400
    out = {"ok": True, "url": url}
    try:
        r = _http.get(url, timeout=25, headers={
            "User-Agent": "Mozilla/5.0 (compatible; kahla-house/1.0)",
            "Accept": "text/html,application/json,text/plain,*/*",
        })
        out["status"] = r.status_code
        body = r.text or ""
        # strip script/style then collapse tags — we want the prose+tables,
        # not the SPA shell
        body = _html_to_text(body)          # ONE implementation (shared
                                            # with the rewards sync)
        out["chars"] = len(body)
        out["text"] = body[:14000]
    except Exception as e:
        out.update(ok=False, error=f"{type(e).__name__}: {e}"[:300])
    _probe_log(out)
    return jsonify(out)


@app.route("/api/polymarket/incentive-config")
def api_poly_incentive_config():
    """PER-MARKET reward configuration — the answer to "what is the
    minimum qualifying order size, and are our 1-4 contract orders even
    earning?".

    The docs state each incentivised market carries its own daily reward
    rate, max qualifying spread and min qualifying order size, readable
    through the API. Our own earnings feed shows outs props earned $14.98
    while K props earned $0.50 on comparable order counts — if the K
    markets' minimum size is above our order size we are taking the
    adverse selection and collecting no rent at all.

    Probes /v1/incentives (offer discovery) and dumps the FULL raw market
    object for sample slugs, since the reward config may ride on the
    market itself. Assumes no field names. Read-only."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    try:
        client = get_client()
    except Exception as e:
        return jsonify({"ok": False, "error": f"client: {e}"}), 500

    def _trim(v, n=3000):
        try:
            s = v if isinstance(v, str) else json.dumps(v, default=str)
        except Exception:
            s = str(v)
        return s[:n]

    out = {"ok": True, "offers": {}, "markets": {}}

    # -- offer discovery: what programs exist / their parameters --
    for label, path, q in (
        ("v1/incentives", "/v1/incentives", None),
        ("v1/incentives?limit", "/v1/incentives", {"limit": 50}),
        ("v1/incentives/programs", "/v1/incentives/programs", None),
    ):
        try:
            out["offers"][label] = _trim(
                client.get(path, query=q, authenticated=True))
        except Exception as e:
            out["offers"][label] = f"{type(e).__name__}: {e}"[:200]

    # -- per-market: the FULL object, so a rewards block can't hide --
    slugs = [s for s in (request.args.get("slugs") or "").split(",") if s]
    if not slugs:
        # live slugs beat historical ones (a closed market may drop its
        # reward config); pull today's from our own recent prop picks
        try:
            sb = get_supabase()
            rows = (sb.table("bot_picks")
                    .select("signal_blob")
                    .eq("status", "pending")
                    .order("picked_at", desc=True)
                    .limit(40).execute().data) or []
            for r in rows:
                b = r.get("signal_blob") or {}
                s = (b.get("pmm") or {}).get("slug") or b.get("pmm_slug")
                if s and s not in slugs:
                    slugs.append(s)
                if len(slugs) >= 6:
                    break
        except Exception as e:
            out["slug_lookup_error"] = str(e)[:200]
    out["slugs_probed"] = slugs

    for s in slugs[:6]:
        entry = {}
        try:
            m = client.markets.retrieve_by_slug(s)
            entry["market_keys"] = sorted((m or {}).keys()) \
                if isinstance(m, dict) else str(type(m))
            # any key that smells like reward config, verbatim
            if isinstance(m, dict):
                entry["reward_fields"] = {
                    k: v for k, v in m.items()
                    if re.search(r"reward|incentive|rate|min|max|spread|size",
                                 str(k), re.I)}
            entry["raw"] = _trim(m, 2000)
        except Exception as e:
            entry["market_error"] = f"{type(e).__name__}: {e}"[:200]
        try:
            # `symbols` is the documented filter (marketSlug is the
            # EARNINGS param and is silently ignored here — it returned the
            # whole catalog and briefly looked like "props have no program")
            entry["incentive_by_symbols"] = _trim(client.get(
                "/v1/incentives", query={"symbols": s},
                authenticated=True), 1500)
        except Exception as e:
            entry["incentive_by_symbols"] = f"{type(e).__name__}: {e}"[:200]
        out["markets"][s] = entry

    _probe_log(out)
    return jsonify(out)


# ── FOOTBALL GO-LIVE RECON (Aug 18 2026) ───────────────────────────────
_FB_RECON_SPORTS = ("NFL", "NCAAF")


def _fb_h_to_kick(iso_win, iso_kick):
    """Hours from a program-window edge to kickoff (positive = that many
    hours BEFORE kickoff, negative = after it). Every reward window is
    reported in this form because it is the only one that transfers
    between sports — MLB's answer was ML/O-U opening->start and props
    T-6h->start, and football has fewer, bigger events."""
    try:
        w = datetime.fromisoformat(str(iso_win).replace("Z", "+00:00"))
        k = datetime.fromisoformat(str(iso_kick).replace("Z", "+00:00"))
        return round((k - w).total_seconds() / 3600.0, 1)
    except Exception:
        return None


# PROBED Aug 18 2026, not guessed. NCAAF's tag is `cfb` (182 events, 90
# games); `college-football`, `ncaaf` and `college-football-ncaaf` all
# return ZERO. A wrong tag is indistinguishable from an unlisted sport,
# which is why the recon reports each attempt's own count.
_FB_TAG_CANDS = {
    "NFL":   ["nfl"],
    "NCAAF": ["cfb"],
}


def _fb_is_game(ev: dict) -> bool:
    """A GAME event, not a season future.

    ⚠ "slug ends in a date" is NOT enough (Aug 18, second run): season
    futures carry dates too — nfl-mostrecyds-2027-01-10 is the receiving
    yards leader, nfl-vitvea-2026-09-13 is a Vita Vea next-team market,
    and both sailed through a date-suffix test. A game is TWO TEAMS and a
    date, so the slug needs two team tokens before it — league-away-home-
    date, the same convention as mlb-sea-mil-2026-08-19. Titles that
    actually name two teams ("X vs. Y") pass on their own."""
    t = str(ev.get("title") or "").lower()
    sl = str(ev.get("slug") or "").lower()
    if " vs " in t or " vs. " in t or " @ " in t:
        return True
    return bool(re.match(r"^[a-z]+-[a-z]{2,5}-[a-z]{2,5}-20\d\d-\d\d-\d\d$",
                         sl))


def _fb_market_of_event(md: dict, ev_slug: str) -> bool:
    """Does this market actually belong to that event? The venue's slug
    convention is <prefix>-<event slug>[-suffix], so the event slug (or
    its distinctive tail) has to appear in the market slug."""
    ms = str(md.get("slug") or "").lower()
    ev = str(ev_slug or "").lower()
    if not ms or not ev:
        return False
    if ev in ms:
        return True
    tail = "-".join(ev.split("-")[-3:])          # teams + date
    return bool(tail) and tail in ms


@app.route("/api/football/recon")
def api_football_recon():
    """FOOTBALL GO-LIVE RECON — read-only. Answers the three questions no
    DB row can answer, in one call.

    ⚠ WHY THE DB CANNOT ANSWER THIS. `_incentives_sync` seeds its
    `symbols` filter from OUR OWN earnings + picks (the unfiltered
    catalog does not list game/prop markets — see the landmine there), so
    `poly_incentive_programs` holds programs only for markets we already
    rest orders on. Football is absent from that table because we have
    NEVER BET FOOTBALL, not because football carries no programs. Reading
    the mirror and concluding "no football rent" is the exact shape of
    the bug that once concluded "props have no programs".

      1. LISTING  — does Poly list NFL / NCAAF yet, and how far out?
      2. TAXONOMY — every market type on a football event, so the prop
         inventory is a fact instead of a guess (v1 + v2 + a sample
         question per type; the v1 rename landmine means the v1 strings
         are what any future classifier work keys off).
      3. RENT     — the incentive programs for those exact slugs, each
         period stated relative to kickoff.

    Params: key (shared secret), sports=NFL,NCAAF, events=N (per sport,
    max 6). Persists to exec_probe_runs — read it back with run_sql.sh,
    never by screenshot."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    try:
        client = get_client()
    except Exception as e:
        return jsonify({"ok": False, "error": f"client: {e}"}), 500
    import pmm_markets as _pmm
    try:
        n_ev = max(1, min(6, int(request.args.get("events") or 3)))
    except (TypeError, ValueError):
        n_ev = 3
    sports = [s.strip().upper() for s in
              (request.args.get("sports")
               or ",".join(_FB_RECON_SPORTS)).split(",") if s.strip()]
    win_min = (request.args.get("start_min") or "").strip() or None
    win_max = (request.args.get("start_max") or "").strip() or None
    if win_min and not win_max:
        win_max = (datetime.now(timezone.utc) + timedelta(days=30)).isoformat()
    out = {"ok": True, "at": datetime.now(timezone.utc).isoformat(),
           "sports": {}, "rent": {}}
    probe: list = []                      # (sport, slug, kickoff_iso)

    for sport in sports:
        tags = _FB_TAG_CANDS.get(sport) or (
            [_pmm._SPORT_TAG_SLUG[sport]] if sport in _pmm._SPORT_TAG_SLUG
            else [])
        rec = {"tags_tried": tags, "events": 0, "games": 0,
               "sample": [], "attempts": {}}
        out["sports"][sport] = rec
        if not tags:
            rec["error"] = "no tag candidate"
            continue
        evs, seen = [], set()
        for tag in tags:
            shapes = [{"tagSlug": tag, "closed": False, "limit": 200}]
            if win_min:                    # a time window is what separates
                shapes.insert(0, {         # week-1 GAMES from season futures
                    "tagSlug": tag, "closed": False, "limit": 200,
                    "startTimeMin": win_min, "startTimeMax": win_max})
            for i, params in enumerate(shapes):
                try:
                    resp = client.events.list(params)
                except Exception as e:
                    rec["attempts"]["%s.%d" % (tag, i)] = (
                        f"{type(e).__name__}: {e}"[:160])
                    continue
                got = (resp.get("events") if isinstance(resp, dict)
                       else getattr(resp, "events", None)) or []
                rec["attempts"]["%s.%d" % (tag, i)] = len(got)
                for ev in got:
                    d = _pmm._event_to_dict(ev)
                    sl = d.get("slug")
                    if sl and sl not in seen:
                        seen.add(sl)
                        evs.append(d)
        evs.sort(key=lambda d: str(d.get("startTime") or "z"))
        rec["events"] = len(evs)
        # ⚠ A LEAGUE TAG IS MOSTLY SEASON FUTURES (found Aug 18: sorting the
        # nfl tag by startTime put `nfl-mostpassyds-2027-01-10` and friends
        # first, so the taxonomy pass expanded futures and learned nothing
        # about games). A GAME event is two teams and a date — require it.
        games = [d for d in evs if _fb_is_game(d)]
        rec["games"] = len(games)
        rec["sample"] = [{"slug": d.get("slug"), "title": d.get("title"),
                          "start": d.get("startTime")} for d in games[:12]]
        rec["sample_nongame"] = [{"slug": d.get("slug"),
                                  "start": d.get("startTime")}
                                 for d in evs if not _fb_is_game(d)][:6]
        evs = games
        # -- taxonomy: expand the nearest N events into market types --
        tally, samples = {}, {}
        for d in evs[:n_ev]:
            sl = d.get("slug")
            if not sl:
                continue
            ms = []
            # ⚠ markets.list's eventSlug filter is ADVISORY (Aug 18: asking
            # for an NFL futures event returned MLB and US-election markets
            # — the same "filter silently ignored" shape as `marketSlug` on
            # /v1/incentives). Ask the event for its own markets first, and
            # VERIFY whatever comes back actually belongs to this event.
            try:
                full = client.events.retrieve_by_slug(sl)
                evf = (full.get("event") if isinstance(full, dict)
                       else getattr(full, "event", None)) or full
                ms = (_pmm._event_to_dict(evf) or {}).get("markets") or []
            except Exception as e:
                rec.setdefault("market_errors", []).append(
                    ("retrieve %s: " % sl) + str(e)[:120])
            if not ms:
                try:
                    mresp = client.markets.list({"eventSlug": [sl],
                                                 "closed": False,
                                                 "limit": 200})
                    ms = (mresp.get("markets") if isinstance(mresp, dict)
                          else getattr(mresp, "markets", None)) or []
                    ms = [_pmm._market_to_dict(m) for m in ms]
                except Exception as e:
                    rec.setdefault("market_errors", []).append(
                        ("list %s: " % sl) + str(e)[:120])
            kept = []
            for md in ms:
                if _fb_market_of_event(md, sl):
                    kept.append(md)
            rec.setdefault("verify", {})[sl] = {
                "returned": len(ms), "kept": len(kept)}
            for md in kept:
                v1 = str(md.get("sportsMarketType") or "?")
                tally[v1] = tally.get(v1, 0) + 1
                if v1 not in samples:
                    samples[v1] = {
                        "q": str(md.get("question") or "")[:120],
                        "slug": md.get("slug"),
                        "v2": md.get("sportsMarketTypeV2"),
                        "line": md.get("line"),
                        "bid": ((md.get("bestBidQuote") or {}).get("value")
                                if isinstance(md.get("bestBidQuote"), dict)
                                else None),
                    }
                    if md.get("slug"):
                        probe.append((sport, md["slug"], d.get("startTime")))
        rec["market_types"] = dict(sorted(tally.items(),
                                          key=lambda kv: -kv[1]))
        rec["type_samples"] = samples
        rec["expanded_events"] = min(n_ev, len(evs))

    # ---- 3. RENT: ask the venue about these exact slugs ----
    for sport, slug, kick in probe[:24]:
        entry = {"sport": sport, "kickoff": kick}
        try:
            raw = client.get("/v1/incentives", query={"symbols": slug},
                             authenticated=True) or {}
        except Exception as e:
            entry["error"] = f"{type(e).__name__}: {e}"[:160]
            out["rent"][slug] = entry
            continue
        progs = (raw.get("programs") if isinstance(raw, dict) else None) or []
        entry["programs_returned"] = len(progs)
        periods = []
        for m in progs:
            # the symbols filter has been observed to be advisory (it once
            # returned the whole catalog) — keep only the slug we asked for
            if str(m.get("marketSlug") or "") != slug:
                continue
            kk = m.get("eventStartTime") or kick
            for tp in (m.get("timePeriods") or []):
                periods.append({
                    "type": tp.get("programType"),
                    "period": tp.get("period"),
                    "pool": tp.get("rewardPool"),
                    "df": tp.get("discountFactor"),
                    "target": tp.get("targetSize"),
                    "status": tp.get("status"),
                    "opens_h_before_kick": _fb_h_to_kick(tp.get("start"), kk),
                    "closes_h_before_kick": _fb_h_to_kick(tp.get("end"), kk),
                })
        entry["periods"] = periods
        out["rent"][slug] = entry
    _probe_log(out)
    return jsonify(out)


@app.route("/api/polymarket/incentives")
def api_poly_incentives():
    """PROBE: is there a first-party maker-reward EARNINGS read? (Aug 15
    2026 — user spotted `GET /v1/incentives/earnings` in the Polymarket US
    API surface.) Today every reward number we have is reverse-engineered
    from the activities feed: we see PAYOUTS (lump credits, ~5-7 business
    days after the event-day period) and have to hand-attribute them to
    windows. An earnings read would give ACCRUAL and — if it itemizes —
    PER-MARKET attribution, which is the missing denominator for "does the
    props lane pay for its own rewards".

    PROBE-FIRST, three phases, each independent + never raising (the
    /api/kalshi/probe + /debug-pmm discipline — assume NO field names,
    dump the RAW shape and let the DB row be the ground truth):
      1. DISCOVER — grep the installed SDK source for incentives/earnings
         resources + URL literals, so we learn the real accessor instead
         of guessing it.
      2. SDK CALL — try the plausible accessors found/guessed.
      3. RAW GET — reach the SDK's underlying signed transport and hit
         the path directly, in a few param shapes.
    Shared-secret (?key=FILLS_CRON_SECRET) so the site-curl bridge can
    fire it; result PERSISTED to exec_probe_runs. READ-ONLY — touches no
    order, places nothing, cancels nothing."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403

    import re as _re
    out: dict = {"ok": True, "discover": {}, "sdk": {}, "raw": {}}

    def _trim(v, n=2500):
        """Raw shapes only — never let one fat payload blow the row."""
        try:
            s = v if isinstance(v, str) else json.dumps(v, default=str)
        except Exception:
            s = str(v)
        return s[:n]

    # ---- phase 1: discover what the installed SDK actually exposes ----
    try:
        import polymarket_us as _pm
        out["discover"]["version"] = getattr(_pm, "__version__", "?")
        root = os.path.dirname(_pm.__file__)
        hits, urls, defs = [], set(), set()
        for dirpath, _d, files in os.walk(root):
            for fn in files:
                if not fn.endswith(".py"):
                    continue
                try:
                    src = open(os.path.join(dirpath, fn),
                               encoding="utf-8", errors="ignore").read()
                except Exception:
                    continue
                if not _re.search(r"incentive|earning|reward|liquidity",
                                  src, _re.I):
                    continue
                rel = os.path.relpath(os.path.join(dirpath, fn), root)
                urls.update(_re.findall(r"[\"'](/v\d+/[a-z0-9/_\-{}]*"
                                        r"(?:incentive|earning|reward)"
                                        r"[a-z0-9/_\-{}]*)[\"']", src, _re.I))
                for m in _re.finditer(r"(?:def|class)\s+\w*"
                                      r"(?:incentive|earning|reward)\w*"
                                      r"[^\n]{0,120}", src, _re.I):
                    defs.add(f"{rel}: {m.group(0).strip()}")
                if len(hits) < 25:
                    for m in _re.finditer(r".{0,80}(?:incentive|earning)"
                                          r".{0,80}", src, _re.I):
                        if len(hits) < 25:
                            hits.append(f"{rel}: {m.group(0).strip()}")
        out["discover"].update(url_literals=sorted(urls),
                               definitions=sorted(defs)[:25],
                               context=hits)
    except Exception as e:
        out["discover"]["error"] = str(e)[:200]

    try:
        client = get_client()
    except Exception as e:
        out.update(ok=False, error=f"client: {e}")
        _probe_log(out)
        return jsonify(out)

    # top-level client attributes — names the resource even if our guesses miss
    try:
        out["discover"]["client_attrs"] = sorted(
            a for a in dir(client) if not a.startswith("_"))
    except Exception:
        pass

    # ---- phase 2: call it through the SDK, whatever it's called ----
    for path in ("incentives.earnings", "incentives.list", "incentives.get",
                 "rewards.earnings", "rewards.list", "earnings.list"):
        obj, ok = client, True
        for part in path.split("."):
            obj = getattr(obj, part, None)
            if obj is None:
                ok = False
                break
        if not ok or not callable(obj):
            continue
        try:
            out["sdk"][path] = {"ok": True, "raw": _trim(obj())}
        except Exception as e:
            out["sdk"][path] = {"ok": False,
                                "error": f"{type(e).__name__}: {e}"[:300]}
    if not out["sdk"]:
        out["sdk"]["_note"] = "no matching SDK accessor found — see discover"

    # ---- phase 3: signed GET, via the client's OWN request helpers ----
    # Probe run #1 (id=60) settled the shape: SDK 0.1.2 has no incentives
    # resource, the client itself carries .get/.post (so IT is the signed
    # transport), and client._http is a bare httpx that demands an ABSOLUTE
    # url ("UnsupportedProtocol"). So: prefer client.get (it signs + resolves
    # the base), then fall back to _http against each known base. Still no
    # hand-rolled signature anywhere.
    bases = {}
    for b in ("api_base_url", "gateway_base_url"):
        try:
            bases[b] = str(getattr(client, b, "") or "")
        except Exception:
            bases[b] = "?"
    out["raw"]["bases"] = bases
    paths = ("/v1/incentives/earnings", "/incentives/earnings")

    def _record(label, fn):
        try:
            r = fn()
            body = None
            for meth in ("json", "text"):
                try:
                    body = getattr(r, meth, None)
                    if body is None:
                        continue
                    body = body() if callable(body) else body
                    break
                except Exception:
                    continue
            out["raw"][label] = {
                "status": getattr(r, "status_code", "?"),
                "body": _trim(body if body is not None else r),
            }
        except Exception as e:
            out["raw"][label] = {"error": f"{type(e).__name__}: {e}"[:300]}

    # Run #3 (id=94) read the signature and found the whole bug:
    #     def get(self, path, *, query=None, authenticated=False)
    # `authenticated` DEFAULTS TO FALSE — runs #1-2 sent an UNSIGNED
    # request, which is exactly the "User must be authenticated" we got.
    # (Same reason the paged attempt TypeError'd: the kwarg is `query`,
    # not `params`.) Send it signed.
    for p in paths:
        _record(f"AUTHED {p}",
                lambda p=p: client.get(p, authenticated=True))
    for label, q in (("limit", {"limit": 100}),
                     ("noargs", None)):
        _record(f"AUTHED {paths[0]} ?{label}",
                lambda q=q: client.get(paths[0], query=q,
                                       authenticated=True))
    # keep one unauthenticated control so the row proves the difference
    _record("control-unauthed", lambda: client.get(paths[0]))

    # ---- phase 3b: AGGREGATE (run #4 struck oil) ----
    # The signed call returns {"rewards":[{reward, programType, marketSlug,
    # date, status}, ...]} — per-MARKET, per-DAY, with PENDING status. That
    # is attribution + accrual + grain, the three things the activities feed
    # could never give us. The raw body is trimmed for the row, so totals
    # are computed here from the FULL payload.
    try:
        data = client.get(paths[0], authenticated=True)
        rows = (data or {}).get("rewards") or []
        agg = {"n": len(rows), "total": 0.0, "by_status": {},
               "by_date": {}, "by_kind": {}, "top": []}

        def _kind(slug: str) -> str:
            """aec-* are game markets; astatc-* carry the pstat family as a
            token (…-ha-edurod-gte6). Anything else stays labelled raw so a
            new prefix can't be silently folded into the wrong bucket."""
            s = slug or ""
            if s.startswith("aec-"):
                return "game (ML/total)"
            if s.startswith("astatc-"):
                for fam in ("-k-", "-outs-", "-ha-", "-bb-"):
                    if fam in s:
                        return f"prop {fam.strip('-')}"
                return "prop other"
            return f"other:{s.split('-')[0] if s else '?'}"

        for r in rows:
            amt = _safe_float(r.get("reward")) or 0.0
            st = str(r.get("status") or "?")
            dt = str(r.get("date") or "?")
            kd = _kind(str(r.get("marketSlug") or ""))
            agg["total"] += amt
            agg["by_status"][st] = round(
                agg["by_status"].get(st, 0.0) + amt, 4)
            agg["by_date"][dt] = round(agg["by_date"].get(dt, 0.0) + amt, 4)
            agg["by_kind"][kd] = round(agg["by_kind"].get(kd, 0.0) + amt, 4)
        agg["total"] = round(agg["total"], 4)
        agg["top"] = sorted(
            ({"slug": str(r.get("marketSlug") or ""),
              "reward": _safe_float(r.get("reward")) or 0.0,
              "date": str(r.get("date") or ""),
              "status": str(r.get("status") or "")} for r in rows),
            key=lambda r: r["reward"], reverse=True)[:15]
        agg["program_types"] = sorted(
            {str(r.get("programType") or "?") for r in rows})
        out["agg"] = agg
    except Exception as e:
        out["agg"] = {"error": f"{type(e).__name__}: {e}"[:300]}

    # ---- phase 4: HOW does a WORKING call authenticate? ----
    # Run #2 proved the route is real: /v1/incentives/earnings returns
    # AuthenticationError while /incentives/earnings returns NotFound — a
    # missing path 404s, so ours exists and we simply aren't signing it.
    # client.get is plainly a raw helper; the resource methods
    # (portfolio.positions et al) DO authenticate. Read their source and
    # find the signed request helper instead of inventing headers.
    out["auth"] = {}
    try:
        import inspect as _insp
        try:
            out["auth"]["client_get_src"] = _trim(
                _insp.getsource(type(client).get), 1800)
        except Exception as e:
            out["auth"]["client_get_src"] = f"err: {e}"[:200]
        port = getattr(client, "portfolio", None)
        if port is not None:
            out["auth"]["portfolio_attrs"] = sorted(
                a for a in dir(port) if not a.startswith("__"))
            for m in ("positions", "activities"):
                fn = getattr(port, m, None)
                if fn is None:
                    continue
                try:
                    out["auth"][f"portfolio.{m}_src"] = _trim(
                        _insp.getsource(fn), 1800)
                except Exception as e:
                    out["auth"][f"portfolio.{m}_src"] = f"err: {e}"[:200]
                break
        # every private callable on the client — the signed helper is here
        out["auth"]["client_private"] = sorted(
            a for a in dir(client)
            if a.startswith("_") and not a.startswith("__")
            and callable(getattr(client, a, None)))
    except Exception as e:
        out["auth"]["error"] = str(e)[:200]

    # the auth header literals the SDK builds, wherever it builds them
    try:
        import polymarket_us as _pm2
        root2 = os.path.dirname(_pm2.__file__)
        hdrs, sign_ctx = set(), []
        for dirpath, _d, files in os.walk(root2):
            for fn in files:
                if not fn.endswith(".py"):
                    continue
                try:
                    src = open(os.path.join(dirpath, fn),
                               encoding="utf-8", errors="ignore").read()
                except Exception:
                    continue
                hdrs.update(_re.findall(r"[\"']([A-Za-z\-]*(?:api[_-]?key|"
                                        r"signature|timestamp|authorization|"
                                        r"poly[a-z\-]*)[A-Za-z\-]*)[\"']",
                                        src, _re.I))
                if len(sign_ctx) < 10:
                    for m in _re.finditer(r".{0,100}(?:def _?(?:request|"
                                          r"_signed|sign)\w*|headers\s*=)"
                                          r".{0,100}", src):
                        if len(sign_ctx) < 10:
                            rel = os.path.relpath(
                                os.path.join(dirpath, fn), root2)
                            sign_ctx.append(f"{rel}: {m.group(0).strip()}")
        out["auth"]["header_literals"] = sorted(hdrs)[:30]
        out["auth"]["sign_context"] = sign_ctx
    except Exception as e:
        out["auth"]["grep_error"] = str(e)[:200]

    _probe_log(out)
    return jsonify(out)


@app.route("/api/polymarket/daily-volume")
def api_poly_daily_volume():
    """PER-DAY maker volume from the account's own Polymarket activities
    feed (Aug 8 2026 — stop estimating the maker-reward base from monthly
    totals and assumed-uniform distribution; the July shape is knowable
    because the Kalshi detour left a hole in it). Returns, per ET day:
    trades, distinct market-slugs touched, buy $, sell $, resolution
    payouts. `from`/`to` bound the window (ET dates, `to` exclusive).

    CAVEAT the numbers can't resolve: the feed doesn't flag maker vs
    taker. Every MACHINE order is post-only (maker by construction), but
    hand-placed July fills could include takes. Read the daily shape as
    an upper bound on maker volume, not a certainty."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    lo = request.args.get("from") or "2026-07-01"
    hi = request.args.get("to") or "2026-08-10"
    try:
        client = get_client()
    except Exception as e:
        return jsonify({"ok": False, "error": f"client: {e}"}), 500
    acts, cursor = [], None
    try:
        for _ in range(140):
            params = {"limit": 100}
            if cursor:
                params["cursor"] = cursor
            resp = client.portfolio.activities(params=params)
            page = resp.get("activities", [])
            acts.extend(page)
            times = []
            for a in page:
                for v in a.values():
                    if isinstance(v, dict) and v.get("updateTime"):
                        times.append(str(v["updateTime"]))
                        break
            if times and max(times) < lo:
                break
            if resp.get("eof", True) or not resp.get("nextCursor"):
                break
            cursor = resp.get("nextCursor")
    except Exception as e:
        return jsonify({"ok": False, "error": f"activities: {e}",
                        "fetched": len(acts)}), 500
    days: dict = {}
    for act in acts:
        t = act.get("type")
        if t == "ACTIVITY_TYPE_TRADE":
            d = act.get("trade") or {}
        elif t == "ACTIVITY_TYPE_POSITION_RESOLUTION":
            d = act.get("positionResolution") or {}
        else:
            continue
        ts = str(d.get("updateTime") or "")
        if not ts:
            continue
        try:
            day = (datetime.fromisoformat(ts.replace("Z", "+00:00"))
                   .astimezone(ZoneInfo("America/New_York")).date().isoformat())
        except Exception:
            continue
        if day < lo or day >= hi:
            continue
        D = days.setdefault(day, {"trades": 0, "buy": 0.0, "sell": 0.0,
                                  "payout": 0.0, "slugs": set()})
        slug = d.get("marketSlug") or ""
        if slug:
            D["slugs"].add(slug)
        if t == "ACTIVITY_TYPE_POSITION_RESOLUTION":
            D["payout"] += _safe_float(d.get("payout")) or 0.0
            continue
        cost = _safe_float(d.get("cost"))
        if cost is None:
            continue
        D["trades"] += 1
        # SELL iff realizedPnl non-null OR the position shrank — the
        # documented null-netPosition trap (money-ledger lesson).
        bef = d.get("beforePosition") or {}
        aft = d.get("afterPosition") or {}
        nb = _safe_float(bef.get("netPosition"))
        na = _safe_float(aft.get("netPosition"))
        is_sell = (_safe_float(d.get("realizedPnl")) is not None
                   or (nb is not None and na is not None and abs(na) < abs(nb)))
        if is_sell:
            D["sell"] += abs(cost)
        else:
            D["buy"] += abs(cost)
    out_days = {k: {"trades": v["trades"], "markets": len(v["slugs"]),
                    "buy_usd": round(v["buy"], 2),
                    "sell_usd": round(v["sell"], 2),
                    "payout_usd": round(v["payout"], 2)}
                for k, v in sorted(days.items())}
    tot = {"trades": sum(d["trades"] for d in out_days.values()),
           "buy_usd": round(sum(d["buy_usd"] for d in out_days.values()), 2),
           "days_active": len([d for d in out_days.values() if d["trades"]])}
    out = {"ok": True, "from": lo, "to": hi, "activities_scanned": len(acts),
           "total": tot, "days": out_days}
    try:
        get_supabase().table("exec_probe_runs").insert(
            {"params": {"kind": "daily_volume", "from": lo, "to": hi},
             "result": out}).execute()
    except Exception:
        pass
    return jsonify(out)


@app.route("/api/polymarket/fill-times")
def api_poly_fill_times():
    """Per-fill timestamps for the account's BUY trades (Aug 9 2026 — the
    resting-window / fill-window analysis: win rate by how close to first
    pitch each fill landed; nothing stores fill times, the activities feed
    has them). READ-ONLY venue-truth probe (the daily-volume pattern):
    shared-secret, fired via the site-curl bridge, result persisted to
    exec_probe_runs for run_sql.sh readback. `days` bounds the lookback
    (default 10, max 40). Sells/resolutions excluded — same sell test as
    daily-volume (realizedPnl non-null OR position shrank)."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    try:
        days = min(int(request.args.get("days", 10)), 40)
    except ValueError:
        days = 10
    lo_s = (datetime.now(timezone.utc)
            - timedelta(days=days)).strftime("%Y-%m-%dT%H:%M:%S")
    try:
        client = get_client()
    except Exception as e:
        return jsonify({"ok": False, "error": f"client: {e}"}), 500
    buys, scanned, cursor = [], 0, None
    try:
        for _ in range(140):
            params = {"limit": 100}
            if cursor:
                params["cursor"] = cursor
            resp = client.portfolio.activities(params=params)
            page = resp.get("activities", [])
            scanned += len(page)
            times = []
            for a in page:
                d = None
                if a.get("type") == "ACTIVITY_TYPE_TRADE":
                    d = a.get("trade") or {}
                else:
                    for v in a.values():
                        if isinstance(v, dict) and v.get("updateTime"):
                            times.append(str(v["updateTime"])[:19])
                            break
                    continue
                ts = str(d.get("updateTime") or "")[:19]
                if ts:
                    times.append(ts)
                if not ts or ts < lo_s:
                    continue
                bef = d.get("beforePosition") or {}
                aft = d.get("afterPosition") or {}
                nb = _safe_float(bef.get("netPosition"))
                na = _safe_float(aft.get("netPosition"))
                is_sell = (_safe_float(d.get("realizedPnl")) is not None
                           or (nb is not None and na is not None
                               and abs(na) < abs(nb)))
                if is_sell:
                    continue
                buys.append({"slug": d.get("marketSlug") or "", "t": ts,
                             "cost": round(_safe_float(d.get("cost"))
                                           or 0.0, 2),
                             "qty": _safe_float(d.get("qty"))})
            if times and max(times) < lo_s:
                break
            if resp.get("eof", True) or not resp.get("nextCursor"):
                break
            cursor = resp.get("nextCursor")
    except Exception as e:
        return jsonify({"ok": False, "error": f"activities: {e}",
                        "fetched": len(buys)}), 500
    out = {"ok": True, "since": lo_s, "activities_scanned": scanned,
           "n_buys": len(buys), "buys": buys}
    try:
        get_supabase().table("exec_probe_runs").insert(
            {"params": {"kind": "fill_times", "days": days},
             "result": out}).execute()
    except Exception:
        pass
    return jsonify(out)


_TOPUP_BUDGET_S = 5.0     # wall-clock stop for LIVE top-ups (see below)


def _cancel_live_buys_tick(sb, now) -> dict:
    """Cancel model BUY orders resting on a game that has already started.
    The engine behind /api/polymarket/cancel-live-buys, run every minute.

    Cheap by construction: it only touches the venue when a pending model
    pick's game has started in the last 12h, which on most ticks is a
    short list and often empty. Never raises."""
    res = {"swept": 0}
    try:
        owner = _kalshi_owner_uid()
        if not owner:
            return res
        rows = (sb.table("bot_picks")
                .select("event_name,market_type,event_start,signal_blob")
                .eq("asked_by", owner).eq("status", "pending")
                .lt("event_start", now.isoformat())
                .gte("event_start", (now - timedelta(hours=12)).isoformat())
                .limit(300).execute().data) or []
        live: dict = {}
        for r in rows:
            b = r.get("signal_blob") or {}
            if not (b.get("autobet") or b.get("whiff_autobet")
                    or b.get("ou_trader")):
                continue
            slug = b.get("pmm_slug") or (
                (b.get("execution") or {}).get("pmm_slug")
                if isinstance(b.get("execution"), dict) else None)
            if slug:
                live[slug] = r.get("event_name")
        if not live:
            return res                     # nothing live — no venue call
        client = get_client()
        orders = _pmm_open_orders_raw(client)
        if orders is None:
            return res                     # venue dark — never act blind
        for o in orders:
            if "BUY" not in (o.get("intent") or ""):
                continue                   # sells rest through the game
            if not o.get("auto") or o.get("slug") not in live:
                continue                   # hand-placed orders untouchable
            try:
                client.orders.cancel(o["id"], {"marketSlug": o["slug"]})
                res["swept"] += 1
                _send_fill_telegram(
                    f"🧹 FIRST-PITCH SWEEP — {live[o['slug']]}: canceled a "
                    f"resting buy on a game already underway (stale expiry)")
            except Exception:
                pass                       # already gone / venue raced us
    except Exception as e:
        res["err"] = str(e)[:100]
    return res


def _acts_state_save(sb, cursor, done, walked):
    try:
        sb.table("poly_activities_state").upsert(
            {"id": 1, "backfill_cursor": cursor, "backfill_done": bool(done),
             "pages_walked": int(walked),
             "updated_at": datetime.now(timezone.utc).isoformat()},
            on_conflict="id").execute()
    except Exception:
        pass


@app.route("/api/polymarket/acts-backfill")
def api_poly_acts_backfill():
    """Walk the activities feed BACKWARDS into poly_activities, resumably.

    A serverless call can't hold the whole feed, so each call walks a
    bounded number of pages from the stored cursor and saves where it got
    to. Fire it repeatedly (site-curl `repeat=N`) until `done` is true.
    Idempotent — upserts on key, so overlapping calls cost nothing."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    # ⚠ SMALL BATCHES, AND SAVE AFTER EVERY PAGE. The first version
    # walked 20 pages before writing anything and never completed: the
    # call outran the function limit, so nothing was stored, the cursor
    # bookmark never advanced, and no probe row was written either — it
    # failed completely silently. Same lesson as the top-up endpoint.
    try:
        pages = max(1, min(10, int(request.args.get("pages") or 4)))
    except (TypeError, ValueError):
        pages = 4
    try:
        sb, client = get_supabase(), get_client()
    except Exception as e:
        return jsonify({"ok": False, "error": f"client: {e}"}), 500
    st = {}
    try:
        r = (sb.table("poly_activities_state").select("*")
             .eq("id", 1).limit(1).execute().data) or []
        st = r[0] if r else {}
    except Exception:
        pass
    full = request.args.get("full") == "1"
    # ⚠ full=1 must RESPECT a stamped done. The first version let full
    # bypass it so the one-time genesis walk could get past the old
    # cutoff-era stamp — and the very next queued pass then restarted
    # from the TOP of the feed (done cleared the cursor), re-walked
    # already-stored recent pages, and re-stamped done=false: an
    # un-completion loop where every extra pass undid the finish
    # (caught live Aug 22 2026, pages 150→182 storing 1 new row).
    # Genesis is reached; any deliberate re-walk goes through restart=1.
    if st.get("backfill_done") and request.args.get("restart") != "1":
        return jsonify({"ok": True, "done": True, "note": "already complete"})
    cursor = None if request.args.get("restart") == "1" else st.get("backfill_cursor")
    walked = int(st.get("pages_walked") or 0)
    stored, done, oldest = 0, False, None
    try:
        for _ in range(pages):
            params = {"limit": 100}
            if cursor:
                params["cursor"] = cursor
            resp = client.portfolio.activities(params=params)
            page = resp.get("activities", []) or []
            stored += _acts_store(sb, page)
            walked += 1
            for a in page:
                t = str(_act_at(a) or "")
                if t and (oldest is None or t < oldest):
                    oldest = t
            nxt = resp.get("nextCursor")
            if not page or resp.get("eof", True) or not nxt:
                done = True
                break
            cursor = nxt
            # Bookmark after EVERY page, not at the end — a call that
            # dies mid-walk must not lose the pages it already stored.
            _acts_state_save(sb, cursor, False, walked)
            # &full=1 walks to the feed's TRUE end. The cutoff stop was
            # fine for the dashboard's windowed reads, but it stamped
            # backfill_done with pre-cutoff history unread — caught by the
            # ledger itself: a $50 withdrawal on Mar 7 preceded every
            # recorded deposit, which is impossible. A lifetime equation
            # needs genesis, not a horizon.
            if not full and oldest and oldest < _ACTS_CUTOFF:
                done = True               # past the dashboard's horizon
                break
    except Exception as e:
        out = {"ok": False, "error": str(e)[:200], "stored": stored,
               "pages_walked": walked}
        _probe_log(out)                   # failures must leave a trace too
        return jsonify(out), 502
    _acts_state_save(sb, (None if done else cursor), done, walked)
    total = None
    try:
        total = (sb.table("poly_activities").select("key", count="exact")
                 .limit(1).execute()).count
    except Exception:
        pass
    out = {"ok": True, "done": done, "stored_this_call": stored,
           "pages_walked": walked, "oldest_seen": oldest, "total_rows": total}
    _probe_log(out)
    return jsonify(out)


@app.route("/api/polymarket/probe-tif")
def api_poly_probe_tif():
    """Enumerate every TIME_IN_FORCE literal the installed SDK knows about.

    WHY (Aug 12 2026): the app's order ticket offers "Start of game" as an
    expiry, and a hand-placed order with it dies at first pitch. Ours use
    `TIME_IN_FORCE_GOOD_TILL_DATE` + a timestamp WE compute from our own
    stored `event_start`, and one of those filled 13 minutes past its
    expiry (the CIN@CWS YRFI). `docs/repeg-bot-spec.md` claims there is no
    start-of-game literal — but that introspection was done Aug 2 and the
    app plainly has the option, so the claim needs re-checking against the
    SDK that is actually deployed rather than a note.

    Read-only: greps the installed package source for the literals and
    reports the version. No orders touched."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    import re as _re
    out: dict = {"ok": True}
    try:
        import polymarket_us as _pm
        out["version"] = getattr(_pm, "__version__", "?")
        root = os.path.dirname(_pm.__file__)
        lits: set = set()
        tif_ctx: list = []
        for dirpath, _d, files in os.walk(root):
            for fn in files:
                if not fn.endswith(".py"):
                    continue
                try:
                    src = open(os.path.join(dirpath, fn),
                               encoding="utf-8", errors="ignore").read()
                except Exception:
                    continue
                lits.update(_re.findall(r"TIME_IN_FORCE_[A-Z_]+", src))
                for m in _re.finditer(r".{0,90}(?:goodTillTime|GoodTill|"
                                      r"start_of_game|StartOfGame|GAME)"
                                      r".{0,90}", src):
                    if len(tif_ctx) < 12:
                        tif_ctx.append(f"{fn}: {m.group(0).strip()}")
        out["time_in_force_literals"] = sorted(lits)
        out["context"] = tif_ctx
    except Exception as e:
        out.update(ok=False, error=str(e)[:200])
    _probe_log(out)
    return jsonify(out)


@app.route("/api/polymarket/rewards-sync")
def api_poly_rewards_sync():
    """Mirror the live reward schedule (polymarket.us/rewards) into
    poly_reward_schedule — the table the RENT RULE reads.

    This is what keeps the rule honest as the calendar moves: football
    programs are provisioned a couple of weeks out, so a family that
    pays nothing today can start paying without any code change. It also
    reports NEWLY seen programs, which is the 'football has arrived'
    signal we would otherwise have to check by hand."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    try:
        sb = get_supabase()
    except Exception as e:
        return jsonify({"ok": False, "error": f"client: {e}"}), 500
    out = _reward_schedule_sync(sb)
    _RENT_LIVE_CACHE.pop("v", None)          # next read sees the new rows
    out["rent_map"] = {f"{k[0]}/{k[1]}": sorted(v)
                       for k, v in sorted(_rent_periods_live(sb).items())}
    out["ok"] = "err" not in out
    _probe_log(out)
    return jsonify(out)


@app.route("/api/polymarket/cancel-ou")
def api_poly_cancel_ou():
    """Cancel every RESTING, UNFILLED O/U buy the trader lane placed.

    The lane itself is off (OU_TRADER_ENABLED=False — there is no MLB
    totals reward program), but switching off placement does not retire
    the orders already on the book: each one is still a bet waiting to
    happen. "No more bets on O/U" means those come off too.

    Only UNFILLED orders are touched. A filled O/U position is a
    position, not an order — it grades out normally and any harvest sell
    already resting on it stays put; unwinding one is a sell decision
    nobody has made.

    Same three gates as reset-sells / cancel-live-buys: BUY intent,
    AUTOMATIC flag (the app's own orders are MANUAL, so a hand-placed bid
    can never be touched), and the slug must belong to one of OUR pending
    ou_trader picks. Shared-secret + `&dry=1`."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    dry = request.args.get("dry") == "1"
    try:
        sb, client = get_supabase(), get_client()
    except Exception as e:
        return jsonify({"ok": False, "error": f"client: {e}"}), 500
    owner = _kalshi_owner_uid()
    if not owner:
        return jsonify({"ok": False, "error": "no owner uid"}), 500
    mine: dict = {}
    try:
        rows = (sb.table("bot_picks")
                .select("event_name,event_start,entry_price,poly_pnl,"
                        "signal_blob")
                .eq("asked_by", owner).eq("status", "pending")
                .eq("market_type", "total").limit(500).execute().data) or []
    except Exception as e:
        return jsonify({"ok": False, "error": f"picks: {e}"}), 500
    for r in rows:
        b = r.get("signal_blob") or {}
        if not b.get("ou_trader"):
            continue                       # this lane only
        slug = b.get("pmm_slug")
        if slug:
            mine[slug] = r.get("event_name")
    out = {"ok": True, "dry": dry, "ou_pending": len(mine),
           "canceled": 0, "orders": []}
    if not mine:
        return jsonify(out)                # nothing ours — no venue call
    orders = _pmm_open_orders_raw(client)
    if orders is None:
        return jsonify({"ok": False, "error": "venue read failed"}), 503
    for o in orders:
        if "BUY" not in (o.get("intent") or ""):
            continue                       # never touch the harvest sells
        if not o.get("auto") or o.get("slug") not in mine:
            continue                       # hand-placed orders untouchable
        # price_yes is YES-CANONICAL (gotcha #23): on a synthetic NO side
        # the real per-share price is 1 - price. Listed raw and labelled
        # so a dry run is never misread as "we bid 70c on the under".
        rec = {"slug": o.get("slug"), "game": mine.get(o.get("slug")),
               "price_yes_c": (round(o["price_yes"] * 100, 1)
                               if o.get("price_yes") is not None else None),
               "qty": o.get("qty"), "filled": o.get("cum"),
               "unfilled": o.get("leaves"), "state": o.get("state")}
        if dry:
            out["orders"].append(rec)
            continue
        try:
            client.orders.cancel(o["id"], {"marketSlug": o["slug"]})
            rec["canceled"] = True
            out["canceled"] += 1
        except Exception as e:
            rec["error"] = f"{type(e).__name__}: {e}"[:120]
        out["orders"].append(rec)
    if out["canceled"]:
        _send_fill_telegram(
            f"\U0001f6d1 O/U LANE KILLED — canceled {out['canceled']} resting "
            f"total order(s). No MLB totals reward program exists.")
    _probe_log(out)
    return jsonify(out)


@app.route("/api/polymarket/manual-order", methods=["POST"])
@admin_required
def api_poly_manual_order():
    """MANUAL bet from the website (user, Aug 22 2026: "Ya know what
    would be handy??? If there was a way for me to manually bet on a
    game via my website!").

    Places a REAL post-only Polymarket order under the MANUAL order
    indicator — the same flag the venue's own app uses — so every
    machine sweep (dedup, topup, cancel-*, re-peg) is structurally
    blind to it: hand bets are never touched by automation, exactly as
    the AUTOMATIC-gated sweeps were designed. Admin-gated via Firebase
    (this is a human on the site, not a cron).

    body: {slug, synthetic, price_c, contracts, event_start,
           preview: true|false}
    preview=true returns the side's live book + a suggested peg and
    places nothing. Rails on placement: half-cent price grid, must not
    cross the book (post-only would reject anyway — fail loud instead),
    contracts 1-250, cost ≤ $500 fat-finger cap, GTD = kickoff (a
    pre-game bet must not rest into the live game). The RENT RULE does
    not gate this: it governs COMPUTER bets; a human clicking a button
    is the human's own call."""
    body = request.get_json(silent=True) or {}
    slug = str(body.get("slug") or "").strip()
    synthetic = bool(body.get("synthetic"))
    if not slug:
        return jsonify({"ok": False, "error": "slug required"}), 400
    try:
        client = get_client()
    except Exception as e:
        return jsonify({"ok": False, "error": f"client: {e}"}), 500
    book = _pmm_book(client, slug)
    if book is None:
        return jsonify({"ok": False,
                        "error": "book unreadable — try again"}), 503
    # our-side view: a synthetic NO side reads the inverted ladder
    if synthetic:
        s_bid = (100 - book["best_ask"]) if book["best_ask"] is not None else None
        s_ask = (100 - book["best_bid"]) if book["best_bid"] is not None else None
    else:
        s_bid, s_ask = book["best_bid"], book["best_ask"]
    if body.get("preview"):
        sugg = (float(int(s_bid)) + 1.0) if s_bid is not None else None
        if (sugg is not None and s_ask is not None and sugg >= s_ask
                and s_bid is not None):
            sugg = s_bid                 # one-tick book — join, don't cross
        return jsonify({"ok": True, "preview": True, "slug": slug,
                        "side_bid_c": s_bid, "side_ask_c": s_ask,
                        "suggest_c": sugg})
    try:
        price_c = float(body.get("price_c"))
        contracts = int(body.get("contracts"))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "price_c and contracts "
                        "must be numbers"}), 400
    if abs(price_c * 2 - round(price_c * 2)) > 1e-6:
        return jsonify({"ok": False,
                        "error": "price must be on the half-cent grid"}), 400
    if not (1.0 <= price_c <= 99.0):
        return jsonify({"ok": False, "error": "price must be 1-99¢"}), 400
    if not (1 <= contracts <= 250):
        return jsonify({"ok": False, "error": "contracts must be 1-250"}), 400
    cost = contracts * price_c / 100.0
    if cost > 500.0:
        return jsonify({"ok": False, "error": f"cost ${cost:.2f} over the "
                        "$500 fat-finger cap"}), 400
    if s_ask is not None and price_c >= s_ask:
        return jsonify({"ok": False, "error": f"{price_c:g}¢ crosses the "
                        f"{s_ask:g}¢ ask — post-only would reject; bid "
                        "below the ask"}), 400
    try:
        dt = datetime.fromisoformat(
            str(body.get("event_start")).replace("Z", "+00:00"))
        gtt = dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    except (TypeError, ValueError):
        return jsonify({"ok": False,
                        "error": "event_start (ISO) required — orders "
                        "expire at kickoff"}), 400
    canon = (100.0 - price_c) / 100.0 if synthetic else price_c / 100.0
    params = {"marketSlug": slug,
              "intent": ("ORDER_INTENT_BUY_SHORT" if synthetic
                         else "ORDER_INTENT_BUY_LONG"),
              "type": "ORDER_TYPE_LIMIT",
              "price": {"value": f"{canon:.3f}", "currency": "USD"},
              "quantity": contracts,
              "tif": "TIME_IN_FORCE_GOOD_TILL_DATE", "goodTillTime": gtt,
              "participateDontInitiate": True,
              "manualOrderIndicator": "MANUAL_ORDER_INDICATOR_MANUAL"}
    try:
        cr = client.orders.create(params)
        oid = (cr.get("id") if isinstance(cr, dict)
               else getattr(cr, "id", None))
    except Exception as e:
        return jsonify({"ok": False,
                        "error": f"create failed: {e}"[:200]}), 502
    # orders.list is the only truthful read (retrieve 404s on live
    # orders — the probe-proven landmine). Post-only rejections show up
    # here as a missing/rejected order rather than a resting one.
    state = None
    try:
        for o in (_pmm_open_orders_raw(client) or []):
            if o.get("id") == oid:
                state = o.get("state")
                break
    except Exception:
        pass
    _probe_log({"manual_order": True, "slug": slug, "price_c": price_c,
                "contracts": contracts, "synthetic": synthetic,
                "order_id": oid, "state": state})
    return jsonify({"ok": True, "order_id": oid, "state": state,
                    "resting": state in _OPEN_ORDER_STATES,
                    "cost": round(cost, 2)})


@app.route("/api/polymarket/cancel-gridiron")
def api_poly_cancel_gridiron():
    """Cancel every RESTING, UNFILLED football (gridiron_autobet) buy and
    remove its book row once the venue confirms nothing filled.

    Built Aug 22 2026, go-live hour two: with no PIN anchor,
    best_line_for handed the bet leg the FIRST ladder rung the API
    listed — the machine's first NFL bet was GB@MIN under 25.5 at 7¢
    against a real total of ~44.5. The selector is fixed (no anchor →
    the rung priced nearest 50¢); this sweep retires anything placed on
    a wrong rung. The fixed code re-bets the correct line via the
    week-of sweep, so a canceled order here is not a lost bet.

    Same three gates as cancel-ou / reset-sells: BUY intent, AUTOMATIC
    flag (hand-placed orders untouchable), slug must belong to one of
    OUR pending gridiron_autobet picks. The pick row is DELETED only
    after a live cancel AND a venue positions read showing zero holding
    on that slug — the book must mirror the venue, in both directions.
    Shared-secret + `&dry=1`."""
    key = request.args.get("key", "")
    want = (os.environ.get("FILLS_CRON_SECRET") or "").strip()
    if not want or key != want:
        return jsonify({"ok": False, "error": "forbidden"}), 403
    dry = request.args.get("dry") == "1"
    try:
        sb, client = get_supabase(), get_client()
    except Exception as e:
        return jsonify({"ok": False, "error": f"client: {e}"}), 500
    owner = _kalshi_owner_uid()
    if not owner:
        return jsonify({"ok": False, "error": "no owner uid"}), 500
    mine: dict = {}
    try:
        rows = (sb.table("bot_picks").select("id,event_name,signal_blob")
                .eq("asked_by", owner).eq("status", "pending")
                .limit(500).execute().data) or []
    except Exception as e:
        return jsonify({"ok": False, "error": f"picks: {e}"}), 500
    for r in rows:
        b = r.get("signal_blob") or {}
        if b.get("source") != "gridiron_autobet":
            continue                       # this lane only
        slug = b.get("pmm_slug")
        if slug:
            mine[slug] = {"pick_id": r["id"], "game": r.get("event_name")}
    out = {"ok": True, "dry": dry, "gridiron_pending": len(mine),
           "canceled": 0, "picks_removed": 0, "orders": []}
    if not mine:
        return jsonify(out)                # nothing ours — no venue call
    orders = _pmm_open_orders_raw(client)
    if orders is None:
        return jsonify({"ok": False, "error": "venue read failed"}), 503
    for o in orders:
        if "BUY" not in (o.get("intent") or ""):
            continue
        if not o.get("auto") or o.get("slug") not in mine:
            continue
        m = mine[o["slug"]]
        rec = {"slug": o.get("slug"), "game": m["game"],
               "price_yes_c": (round(o["price_yes"] * 100, 1)
                               if o.get("price_yes") is not None else None),
               "qty": o.get("qty"), "filled": o.get("cum"),
               "state": o.get("state")}
        if dry:
            out["orders"].append(rec)
            continue
        try:
            client.orders.cancel(o["id"], {"marketSlug": o["slug"]})
            rec["canceled"] = True
            out["canceled"] += 1
        except Exception as e:
            rec["error"] = f"{type(e).__name__}: {e}"[:120]
            out["orders"].append(rec)
            continue
        # Book mirrors venue: delete the pick ONLY on venue-confirmed
        # zero holding (a partial fill is a position — it stays and
        # grades; never delete a row money is standing behind).
        # _pmm_positions_raw returns {slug: {...}} or None on read failure
        # (None must read as "held" — never wipe a row on a failed read).
        pos = _pmm_positions_raw(client)
        held = True if pos is None else (o["slug"] in pos)
        if not held:
            try:
                sb.table("bot_picks").delete().eq(
                    "id", m["pick_id"]).execute()
                rec["pick_removed"] = True
                out["picks_removed"] += 1
            except Exception as e:
                rec["pick_error"] = f"{type(e).__name__}: {e}"[:120]
        out["orders"].append(rec)
    if out["canceled"]:
        _send_fill_telegram(
            f"🛑 GRIDIRON RUNG SWEEP — canceled {out['canceled']} football "
            f"order(s) placed on wrong ladder rungs (anchorless "
            f"best_line_for); {out['picks_removed']} book row(s) removed. "
            f"The fixed selector re-bets the real lines.")
    _probe_log(out)
    return jsonify(out)


