def _whiff_snapshot():
    """whiff_iq_snapshot row id=1, 10-min cached. None when absent."""
    now_ts = _time.time()
    c = _WHIFF_SNAP_CACHE.get("v")
    if c is not None and now_ts - _WHIFF_SNAP_CACHE.get("ts", 0) < 600:
        return c or None
    snap = None
    try:
        rows = (get_supabase().table("whiff_iq_snapshot")
                .select("state,engine,built_at").eq("id", 1)
                .limit(1).execute().data) or []
        if rows:
            snap = rows[0].get("state")
    except Exception:
        snap = None
    _WHIFF_SNAP_CACHE.update(v=snap or {}, ts=now_ts)
    return snap


def _whiff_decayed(rows, asof, hl):
    """(Σw·num, Σw·den, Σw) over [[iso_date, den, num], ...]."""
    wn = wd = ww = 0.0
    for d_iso, den, num in rows:
        try:
            age = (asof - datetime.fromisoformat(d_iso).date()).days
        except Exception:
            continue
        w = 0.5 ** (max(age, 0) / hl)
        wn += w * num
        wd += w * den
        ww += w
    return wn, wd, ww


def _whiff_tail_p(snap: dict, pitcher: str, opp: str, line: float,
                  asof) -> tuple[float, int] | None:
    """(P(K >= line), n_starts) or None when unpriceable. Mirrors
    _lib/whiff_iq: log5 matchup rate + leash-mixed binomial tail."""
    lg = snap.get("lg") or {}
    lg_k = float(lg.get("k_bf") or 0.22)
    lg_bf = float(lg.get("bf") or 22.0)
    bf_sd = float(lg.get("bf_sd") or 4.5)
    p = (snap.get("pitchers") or {}).get(pitcher)
    if not p:
        return None
    hist = p.get("hist") or []
    wk, wbf, wn = _whiff_decayed(
        [[h[0], h[1], h[2]] for h in hist], asof, _WHIFF_HL_PITCHER)
    p_rate = (wk + _WHIFF_PRIOR_BF * lg_k) / (wbf + _WHIFF_PRIOR_BF)
    e_bf = (wbf + _WHIFF_PRIOR_STARTS * lg_bf) / (wn + _WHIFF_PRIOR_STARTS)
    trows = (snap.get("teams") or {}).get(opp) or []
    tk, tpa, _ = _whiff_decayed(
        [[t[0], t[1], t[2]] for t in trows], asof, _WHIFF_HL_TEAM)
    opp_rate = (tk + _WHIFF_PRIOR_PA * lg_k) / (tpa + _WHIFF_PRIOR_PA)

    def _odds(x):
        x = min(max(x, 1e-6), 1 - 1e-6)
        return x / (1 - x)
    o = _odds(p_rate) * _odds(opp_rate) / _odds(lg_k)
    rate = o / (1 + o)
    # binomial tail mixed over a discretized-normal leash (BF 6..42)
    weights, tot = [], 0.0
    for bf in range(6, 43):
        z = (bf - e_bf) / bf_sd
        w = math.exp(-0.5 * z * z)
        weights.append((bf, w))
        tot += w
    tail = 0.0
    L = int(line)
    q = 1.0 - rate
    for bf, w in weights:
        w /= tot
        pk = q ** bf
        acc = pk if 0 >= L else 0.0
        for k in range(1, bf + 1):
            pk *= (bf - k + 1) / k * (rate / q)
            if k >= L:
                acc += pk
        tail += w * acc
    return tail, len(hist)


def _pstat_tail_p(snap: dict, pitcher: str, line: float, asof,
                  idx: int = 3, mkey: str = "outs_m", skey: str = "outs_s",
                  floor: float = 0.75) -> tuple[float, float] | None:
    """(P(stat >= line), effective_starts) or None when unpriceable.
    The pitcher-stat prop family pricer (Aug 5-6 2026 — outs, then
    hits/walks allowed; ER failed its backtest and has no family).
    Mirrors backtest_outs_iq/backtest_pitcher_props EXACTLY: per-pitcher
    decay-weighted stat mean/SD (HL 365d) from hist element [idx],
    shrunk toward league (lg[mkey]/lg[skey]) by effective starts, normal
    tail with continuity correction, per-family SD floor. Snapshot
    without the family's lg keys → None (quiet no-op on old state)."""
    lg = snap.get("lg") or {}
    lg_m, lg_s = lg.get(mkey), lg.get(skey)
    if lg_m is None or lg_s is None:
        return None
    p = (snap.get("pitchers") or {}).get(pitcher)
    if not p:
        return None
    rows = []
    for h in (p.get("hist") or []):
        if len(h) > idx and h[idx] is not None:
            try:
                d0 = datetime.fromisoformat(str(h[0])[:10]).date()
                rows.append((d0, float(h[idx])))
            except Exception:
                continue
    if not rows:
        return None
    w = m_acc = 0.0
    for (d0, outs0) in rows:
        wt = 0.5 ** ((asof - d0).days / _WHIFF_HL_PITCHER)
        w += wt
        m_acc += wt * outs0
    if w < _WHIFF_MIN_STARTS:
        return None
    m_p = m_acc / w
    v_acc = 0.0
    for (d0, outs0) in rows:
        wt = 0.5 ** ((asof - d0).days / _WHIFF_HL_PITCHER)
        v_acc += wt * (outs0 - m_p) ** 2
    s_p = math.sqrt(v_acc / w) if w > 0 else float(lg_s)
    m_hat = ((m_p * w + float(lg_m) * _WHIFF_PRIOR_STARTS)
             / (w + _WHIFF_PRIOR_STARTS))
    s_hat = math.sqrt((s_p ** 2 * w + float(lg_s) ** 2 * _WHIFF_PRIOR_STARTS)
                      / (w + _WHIFF_PRIOR_STARTS))
    z = (float(line) - 0.5 - m_hat) / max(floor, s_hat)
    tail = 1.0 - 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))
    return tail, w


