def _sport_pays_game_markets(sb, sport: str) -> bool:
    """Does the venue run ANY game-market rent program for this sport?

    Budget priority, NOT a bet gate -- `_rent_ok` still decides every wager.
    This only answers "is it worth spending capture budget here first", and
    it asks the reward schedule instead of hardcoding an answer, because
    RULE #1's whole lesson is that programs move: NCAAF pays futures only
    TODAY, and the day the venue adds a spread program this starts
    prioritising it with no code change. A hardcoded skip would be exactly
    the recall-from-memory mistake the rent rule exists to prevent.

    Fails OPEN, unlike `_rent_ok`: guessing wrong here costs a little
    capture budget, never a bet resting unpaid.
    """
    try:
        c = _RENT_FAMILY_CACHE
        if c["sports"] is None or _time.time() - c["at"] > 3600:
            rows = (sb.table("poly_reward_schedule").select("sport,family")
                    .limit(2000).execute().data) or []
            pays = set()
            for r in rows:
                fam = (r.get("family") or "").lower()
                sp = (r.get("sport") or "").strip().lower()
                # A blank sport would match EVERY sport under any substring
                # rule, and an empty string is not a sport. Drop it.
                if sp and fam and fam != "futures":
                    pays.add(sp)
            c.update(at=_time.time(), sports=pays)
        pays = c["sports"] or set()
        # EXACT match only. A substring rule reads "nba" as paying because
        # it sits inside "wnba" — caught by a test, and it is the whole
        # class of near-miss this file keeps paying for. If the schedule's
        # vocabulary does not overlap ours AT ALL, the mapping is wrong
        # rather than the answer being "nobody pays", so fail open.
        if not pays or not (pays & _OUR_SPORT_TOKENS):
            return True
        return (sport or "").strip().lower() in pays
    except Exception:
        return True

# --- DIAMOND IQ LIVE ("the steam engine dies tonight" — Aug 2 2026) ---
# MLB moneylines are priced by the MODEL, not by movement: the daily
# compute (kahla-scanner/scripts/compute_diamond_iq.py → diamond_iq_
# snapshot) serializes the walk-forward engine state; _diamond_ml
# reprojects a game from team offense/bullpen + the probable starters'
# FIP factors → pythagenpat P(home). Backtest honesty: ITER1 runs 54.6%
# vs the market's ~57-58% — this lane BETS 1 CONTRACT at openers to
# measure the model against VIRGIN lines (the winnable bar), under the
# same caps as the NRFI lane. Every opener read shadow-logs either way.
_DIQ_CACHE: dict = {"at": 0.0, "snap": None}


def _diamond_snapshot(sb):
    """Latest diamond_iq_snapshot blob, 10-min cached. None = no compute
    yet (lane silently inert — safe-degrade)."""
    if _time.time() - _DIQ_CACHE["at"] < 600 and _DIQ_CACHE["snap"]:
        return _DIQ_CACHE["snap"]
    snap = None
    try:
        rows = (sb.table("diamond_iq_snapshot").select("snapshot")
                .order("id", desc=True).limit(1).execute().data) or []
        snap = rows[0]["snapshot"] if rows else None
    except Exception:
        snap = None
    _DIQ_CACHE.update(at=_time.time(), snap=snap)
    return snap


def _diamond_ml(sb, event_name, away_sp_name, home_sp_name):
    """Model P(home) from the live snapshot; None = can't price (no
    snapshot / team unmatched / cold team — no bet, never a guess). An
    unmatched PITCHER prices as league-average (factor 1.0): the
    probable is an input, not a requirement."""
    snap = _diamond_snapshot(sb)
    if not snap or " @ " not in (event_name or ""):
        return None
    away_n, home_n = [s.strip().lower()
                      for s in event_name.split(" @ ", 1)]
    mc = snap.get("mascot_code") or {}

    def _code(nm):
        for k in sorted(mc, key=len, reverse=True):
            if k in nm:
                return mc[k]
        return None

    teams = snap.get("teams") or {}
    ta, th = teams.get(_code(away_n)), teams.get(_code(home_n))
    ming = snap.get("min_team_games") or 15
    if (not ta or not th or (ta.get("games") or 0) < ming
            or (th.get("games") or 0) < ming):
        return None
    ps = snap.get("pitchers") or {}

    def _fipf(nm):
        p = ps.get((nm or "").strip().lower())
        return p["fip_factor"] if p else 1.0

    shr = snap.get("sp_share") or 0.6

    def _bpf(team_blk):
        """Pen factor with the ITER3 fatigue read (last-2-days reliever
        outs, stamped at compute time)."""
        bpf = team_blk.get("bp_factor") or 1.0
        o2 = team_blk.get("bp_outs2")
        coef = snap.get("bp_fatigue_coef")
        if o2 is not None and coef:
            f = 1.0 + coef * (o2 - (snap.get("bp_fatigue_norm") or 12.0)) / 18.0
            bpf *= max(0.92, min(1.12, f))
        return bpf

    prev_h = shr * _fipf(home_sp_name) + (1 - shr) * _bpf(th)
    prev_a = shr * _fipf(away_sp_name) + (1 - shr) * _bpf(ta)
    lg_rpg = ((snap.get("lg") or {}).get("rpg"))
    # ITER2 live: lineup-wOBA offense factor (last-lineup proxy) when the
    # snapshot has it; else the team-runs read.
    if th.get("off_bf") and lg_rpg:
        xr_h = lg_rpg * th["off_bf"] * prev_a
    else:
        xr_h = (th.get("off") or 0) * prev_a
    if ta.get("off_bf") and lg_rpg:
        xr_a = lg_rpg * ta["off_bf"] * prev_h
    else:
        xr_a = (ta.get("off") or 0) * prev_h
    hc = _code(home_n)
    pf = ((snap.get("park_pf") or {}).get(hc, 100.0)) / 100.0
    xh, xa = xr_h * pf, xr_a * pf
    if xh <= 0 or xa <= 0:
        return None
    xh *= 1.0 + (snap.get("hfa_mult") or 0.08)
    k = max(0.5, (xh + xa) ** (snap.get("pyth_exp") or 0.287))
    return (xh ** k) / (xh ** k + xa ** k)


def _peg_target(bid_c, ask_c, fair_c, join=False):
    """(side_c, entry_edge) — the cheap-first whole-cent peg with every
    gate applied (floor(bid)+1¢; one-cent book → join; virgin book →
    fair−6 anchor; entry cap; ≥2.5pp edge floor). (None, None) = pass.

    join=True pegs AT the touch instead of a cent over it. Both positions
    score DF^0 for our own order, but leading also pushes every other
    resting order down a tick, which is worth ~2.85× the rent per second.
    You trade that away for TIME on the book — the right trade only where
    we'd rather not be filled at all (see _JOIN_TOUCH_FAMS)."""
    if bid_c is not None and bid_c > 0:
        t = float(int(bid_c)) + (0.0 if join else 1.0)
        if ask_c is not None and t >= ask_c:
            t = float(int(bid_c))
    else:
        t = float(int(fair_c - 6.0))
        if ask_c is not None and t >= ask_c:
            t = float(int(ask_c - 1.0))
    e = fair_c - t
    if t <= 0 or t > _REPEG_NRFI_PRICE_CAP_C or e < 2.5:
        return None, None
    return t, e


def _html_to_text(body: str, limit: int = 0) -> str:
    """HTML -> prose+tables text. ONE implementation, shared by
    /api/docs-fetch and the reward-schedule sync — the sync originally
    re-implemented this, skipped the whitespace collapse, and parsed
    ZERO rows because "Program Category Time period" only appears
    contiguously AFTER the collapse. Two copies of a parser is two
    parsers that disagree."""
    body = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", " ", body or "")
    body = re.sub(r"(?s)<[^>]+>", " ", body)
    body = _html.unescape(body)
    body = re.sub(r"&nbsp;?", " ", body)
    body = re.sub(r"\s{2,}", " ", body).strip()
    return body[:limit] if limit else body


