_GRIDIRON_MIN_START = {"NFL": "2026-09-08", "NCAAF": "2026-08-29"}
# THE FIRST FOOTBALL MONEY (user, Aug 22 2026: "ready to put some damn
# money on the NFL YET?? ... Limit to 5 contracts for now"). ML and
